# Strict OOB guard: management network must never be mixed into fabric links.
STRICT_OOB_ISOLATION="${STRICT_OOB_ISOLATION:-true}"

# --- SSH validation tuning ---
SSH_MAX_RETRIES=15
SSH_RETRY_DELAY=10
SSH_TIMEOUT=5

# ======================= COLOUR HELPERS =====================================
RED='\033[0;31m'; GRN='\033[0;32m'; YLW='\033[0;33m'; CYN='\033[0;36m'
BLD='\033[1m'; RST='\033[0m'
log()     { echo -e "${CYN}[$(date '+%H:%M:%S')]${RST} $1" | tee -a "$LOG_FILE"; }
ok()      { echo -e "${GRN}[  OK  ]${RST} $1" | tee -a "$LOG_FILE"; }
warn()    { echo -e "${YLW}[ WARN ]${RST} $1" | tee -a "$LOG_FILE"; }
err()     { echo -e "${RED}[ERROR ]${RST} $1" | tee -a "$LOG_FILE"; }
die()     { err "$1"; exit 1; }
header()  { echo -e "\n${BLD}${CYN}══════ $1 ══════${RST}\n" | tee -a "$LOG_FILE"; }

# ======================= TOPOLOGY MAP =======================================

declare -A VM_TYPE VM_RAM VM_VCPU VM_NICS

apply_profile_settings() {
    local profile="$1"

    case "$profile" in
        win11_kvm)
            AUTOMATION_PROFILE_LABEL="QEMU/KVM on Windows 11"
            PROFILE_IS_LAB=true
            SONIC_RAM=4096;  SONIC_VCPU=4
            SERVER_RAM=1024; SERVER_VCPU=2
            CHR_RAM=512;     CHR_VCPU=1
            ;;
        ubuntu_r620_kvm)
            AUTOMATION_PROFILE_LABEL="QEMU/KVM on Ubuntu for Dell R620"
            PROFILE_IS_LAB=true
            SONIC_RAM=4096;  SONIC_VCPU=2
            SERVER_RAM=8192; SERVER_VCPU=4
            CHR_RAM=1024;    CHR_VCPU=1
            ;;
        ubuntu_r810_kvm)
            AUTOMATION_PROFILE_LABEL="QEMU/KVM on Ubuntu for Dell R810 (256GB/64CPU/5TB)"
            PROFILE_IS_LAB=true
            SONIC_RAM=4096;   SONIC_VCPU=2
            # Role-tiered server resources (differentiated by workload)
            SERVER_CONTROLLER_RAM=32768; SERVER_CONTROLLER_VCPU=10
            SERVER_WORKER_RAM=28672;     SERVER_WORKER_VCPU=10
            SERVER_GATEWAY_RAM=16384;    SERVER_GATEWAY_VCPU=4
            SERVER_RAM=$SERVER_WORKER_RAM; SERVER_VCPU=$SERVER_WORKER_VCPU  # fallback
            CHR_RAM=2048;     CHR_VCPU=2
            # Disk sizes
            SONIC_ROOT_DISK_GB=20
            SERVER_CONTROLLER_ROOT_DISK_GB=80
            SERVER_WORKER_ROOT_DISK_GB=60
            SERVER_GATEWAY_ROOT_DISK_GB=50
            SERVER_ROOT_DISK_GB=60  # fallback
            CHR_ROOT_DISK_GB=5
            CEPH_OSD_DISK_GB=200
            CEPH_OSD_DISKS_PER_NODE=2
            ;;
        real_hardware)
            AUTOMATION_PROFILE_LABEL="Real hardware"
            PROFILE_IS_LAB=false
            SONIC_RAM=0; SERVER_RAM=0; CHR_RAM=0
            SONIC_VCPU=0; SERVER_VCPU=0; CHR_VCPU=0
            ;;
        *)
            die "Unsupported profile '$profile'. Use: win11_kvm, ubuntu_r620_kvm, real_hardware"
            ;;
    esac

    AUTOMATION_PROFILE="$profile"
    export AUTOMATION_PROFILE
}

prompt_for_profile() {
    local choice

    echo "Select automation profile:"
    echo "  1) win11_kvm        - QEMU/KVM on Windows 11 (32GB RAM)"
    echo "  2) ubuntu_r620_kvm  - QEMU/KVM on Ubuntu / Dell R620 (128GB RAM)"
    echo "  3) ubuntu_r810_kvm  - QEMU/KVM on Ubuntu / Dell R810 (256GB RAM)"
    echo "  4) real_hardware    - Physical hardware (no KVM lab deployment)"
    read -r -p "Profile [1]: " choice

    case "${choice:-1}" in
        1) apply_profile_settings "win11_kvm" ;;
        2) apply_profile_settings "ubuntu_r620_kvm" ;;
        3) apply_profile_settings "ubuntu_r810_kvm" ;;
        4) apply_profile_settings "real_hardware" ;;
        *) die "Invalid profile selection: ${choice}" ;;
    esac
}

initialize_vm_catalog() {
    VM_TYPE=()
    VM_RAM=()
    VM_VCPU=()
    VM_NICS=()

    # --- Switches (8 SONiC) ---
    for sw in Spine_S1 Spine_S2 Leaf_L1 Leaf_L2 Leaf_L3 Leaf_L4 Border_Leaf1 Border_Leaf2; do
        VM_TYPE[$sw]="sonic"; VM_RAM[$sw]=$SONIC_RAM; VM_VCPU[$sw]=$SONIC_VCPU; VM_NICS[$sw]=$SONIC_NICS
    done

    # --- Servers (8 Ubuntu) — role-tiered if profile supports it ---
    for sv in Host12_1 Host12_2 Host12_3 Host34_1 Host34_2 HostB12_1 HostB12_2 MonitorSrv; do
        VM_TYPE[$sv]="ubuntu"; VM_NICS[$sv]=$SERVER_NICS
        # Apply role-based resources when tiered values are set (>0)
        case "$sv" in
            Host12_1|Host34_1|HostB12_1)
                # K8s controllers: etcd + apiserver + Ceph MON/OSD + OpenStack ctrl
                VM_RAM[$sv]=${SERVER_CONTROLLER_RAM:-$SERVER_RAM}
                VM_VCPU[$sv]=${SERVER_CONTROLLER_VCPU:-$SERVER_VCPU}
                ;;
            Host12_2|Host12_3|Host34_2)
                # K8s workers: Ceph OSD + Nova compute + app pods
                VM_RAM[$sv]=${SERVER_WORKER_RAM:-$SERVER_RAM}
                VM_VCPU[$sv]=${SERVER_WORKER_VCPU:-$SERVER_VCPU}
                ;;
            HostB12_2|MonitorSrv)
                # Gateway / monitoring nodes (lighter workload)
                VM_RAM[$sv]=${SERVER_GATEWAY_RAM:-$SERVER_RAM}
                VM_VCPU[$sv]=${SERVER_GATEWAY_VCPU:-$SERVER_VCPU}
                ;;
            *)
                VM_RAM[$sv]=$SERVER_RAM; VM_VCPU[$sv]=$SERVER_VCPU
                ;;
        esac
        # Fall back to flat SERVER_RAM if tiered value is 0 (profile doesn't support tiers)
        [[ "${VM_RAM[$sv]}" -eq 0 ]] && VM_RAM[$sv]=$SERVER_RAM
        [[ "${VM_VCPU[$sv]}" -eq 0 ]] && VM_VCPU[$sv]=$SERVER_VCPU
    done

    # --- Exit Routers (2 MikroTik CHR CRS326) ---
    # for er in Exit_Router1 Exit_Router2; do
    #     VM_TYPE[$er]="chr"; VM_RAM[$er]=$CHR_RAM; VM_VCPU[$er]=$CHR_VCPU; VM_NICS[$er]=$CHR_NICS
    # done
    # --- Exit Routers (2 Ubuntu Exit Routers) ---
    for er in Exit_Router1 Exit_Router2; do
    VM_TYPE[$er]="ubuntu"; VM_RAM[$er]=$UBUNTU_EXIT_ROUTER_RAM; VM_VCPU[$er]=$UBUNTU_EXIT_ROUTER_VCPU; VM_NICS[$er]=$UBUNTU_EXIT_ROUTER_NICS
    done
}

print_profile_summary() {
    local total_ram_mb

    if $PROFILE_IS_LAB; then
        # Calculate total based on actual VM catalog (role-aware)
        total_ram_mb=0
        for vm in "${!VM_RAM[@]}"; do
            total_ram_mb=$((total_ram_mb + VM_RAM[$vm]))
        done
        local total_vcpu=0
        for vm in "${!VM_VCPU[@]}"; do
            total_vcpu=$((total_vcpu + VM_VCPU[$vm]))
        done
        log "Profile: $AUTOMATION_PROFILE ($AUTOMATION_PROFILE_LABEL)"
        log "Resource budget:"
        log "  SONiC switches:   ${SONIC_RAM}MB × 8    = $((8 * SONIC_RAM))MB, ${SONIC_VCPU}vCPU × 8 = $((8 * SONIC_VCPU))vCPU"
        if [[ ${SERVER_CONTROLLER_RAM:-0} -gt 0 ]]; then
            log "  K8s controllers:  ${SERVER_CONTROLLER_RAM}MB × 3 = $((3 * SERVER_CONTROLLER_RAM))MB, ${SERVER_CONTROLLER_VCPU}vCPU × 3 = $((3 * SERVER_CONTROLLER_VCPU))vCPU"
            log "  K8s workers:      ${SERVER_WORKER_RAM}MB × 3 = $((3 * SERVER_WORKER_RAM))MB, ${SERVER_WORKER_VCPU}vCPU × 3 = $((3 * SERVER_WORKER_VCPU))vCPU"
            log "  Gateway/monitor:  ${SERVER_GATEWAY_RAM}MB × 2 = $((2 * SERVER_GATEWAY_RAM))MB, ${SERVER_GATEWAY_VCPU}vCPU × 2 = $((2 * SERVER_GATEWAY_VCPU))vCPU"
        else
            log "  Ubuntu servers:   ${SERVER_RAM}MB × 8 = $((8 * SERVER_RAM))MB, ${SERVER_VCPU}vCPU × 8 = $((8 * SERVER_VCPU))vCPU"
        fi
        log "  CHR routers:      ${CHR_RAM}MB × 2    = $((2 * CHR_RAM))MB, ${CHR_VCPU}vCPU × 2 = $((2 * CHR_VCPU))vCPU"
        log "  ─────────────────────────────────────────────────"
        log "  TOTAL:            ${total_ram_mb}MB ($((total_ram_mb / 1024))GB guest RAM), ${total_vcpu} vCPU"
        log "  Disk per OSD:     ${CEPH_OSD_DISK_GB}GB × ${CEPH_OSD_DISKS_PER_NODE} per node"
    else
        log "Profile: $AUTOMATION_PROFILE ($AUTOMATION_PROFILE_LABEL)"
        log "This profile skips KVM lab deployment and is intended for Ansible playbooks against physical switches."
    fi
}

require_lab_profile() {
    local action="$1"

    if ! $PROFILE_IS_LAB; then
        case "$action" in
            destroy|--destroy)
                return 0
                ;;
            *)
                die "The real_hardware profile does not create or manage KVM lab VMs. Run the Ansible playbooks with AUTOMATION_PROFILE=real_hardware instead."
                ;;
        esac
    fi
}

# --- Ordered deployment sequence ---
VM_DEPLOY_ORDER=(
    Spine_S1 Spine_S2
    Leaf_L1 Leaf_L2 Leaf_L3 Leaf_L4
    Border_Leaf1 Border_Leaf2
    Exit_Router1 Exit_Router2
    Host12_1 Host12_2 Host12_3 Host34_1 Host34_2 HostB12_1 HostB12_2 MonitorSrv
)

# --- Fabric point-to-point OVS bridges (29 total) ---
FABRIC_BRIDGES=(
    # Isolated null bridge for NIC-index padding (Accton @49 leaves use br-pad to
    # create real virtio NICs at positions 4-52 so that QSFP+ uplinks land on
    # NIC53/54 = port_config.ini index=53/54 = Ethernet64/68).
    "br-pad"
    # Leaf ↔ Spine (8 links)
    "br-L1-S1" "br-L1-S2"
    "br-L2-S1" "br-L2-S2"
    "br-L3-S1" "br-L3-S2"
    "br-L4-S1" "br-L4-S2"
    # Border-Leaf ↔ Spine (4 links)
    "br-BL1-S1" "br-BL1-S2"
    "br-BL2-S1" "br-BL2-S2"
    # Border-Leaf ↔ Exit Router (4 links: each border-leaf to BOTH exit routers)
    "br-BL1-ER1" "br-BL1-ER2"
    "br-BL2-ER2" "br-BL2-ER1"
    # WAN/ISP bridges (exit routers → simulated ISP uplinks)
    "br-wan1" "br-wan2"
    # Server dual-home links (14 links)
    "br-H121-L1" "br-H121-L2"
    "br-H122-L1" "br-H122-L2"
    "br-H123-L1" "br-H123-L2"
    "br-H341-L3" "br-H341-L4"
    "br-H342-L3" "br-H342-L4"
    "br-MS-L3"   "br-MS-L4"
    "br-HB121-BL1" "br-HB121-BL2"
    "br-HB122-BL1" "br-HB122-BL2"
)

# --- VM → fabric bridge map (NIC0=mgmt, NIC1+=fabric) ---
declare -A VM_BRIDGES
VM_BRIDGES[Spine_S1]="br-L1-S1,br-L2-S1,br-L3-S1,br-L4-S1,br-BL1-S1,br-BL2-S1"
VM_BRIDGES[Spine_S2]="br-L1-S2,br-L2-S2,br-L3-S2,br-L4-S2,br-BL1-S2,br-BL2-S2"
# Accton AS5712-54X leaf wiring — SEQUENTIAL port_config.ini mapping on KVM VS:
#   port_config.ini has 72 ports (48 SFP+ + 6×4 QSFP+ sub-ports, all pre-broken-out).
#   KVM VS maps port N in port_config.ini to kernel interface ethN (NIC-N).
#   The `index` field in port_config.ini is physical cage metadata, NOT the NIC binding.
#
#   NIC1-3:   host downlinks (Ethernet0-2 = SFP+ ports, port_config.ini positions 1-3)
#   @61:      pad NIC4-64  (positions 4-64 = Ethernet3-Ethernet63, unused in lab)
#   NIC65:    Spine_S2 uplink (Ethernet64 = QSFP+5 sub-port, port_config.ini position 65)
#   @3:       pad NIC66-68 (positions 66-68 = Ethernet65-67, unused QSFP+5 sub-ports)
#   NIC69:    Spine_S1 uplink (Ethernet68 = QSFP+6 sub-port, port_config.ini position 69)
#   @3:       pad NIC70-72 (positions 70-72 = Ethernet69-71, unused QSFP+6 sub-ports)
#   Total: 3 + 61 + 1 + 3 + 1 + 3 = 72 data NICs + 1 mgmt = 73 NICs per Accton leaf.
VM_BRIDGES[Leaf_L1]="br-H121-L1,br-H122-L1,br-H123-L1,@61,br-L1-S2,@3,br-L1-S1,@3"
VM_BRIDGES[Leaf_L2]="br-H121-L2,br-H122-L2,br-H123-L2,@61,br-L2-S2,@3,br-L2-S1,@3"
# Arista 7050QX-32/32S leaf and border-leaf wiring — port_config.ini mapping on KVM VS:
#   port_config.ini has 32 QSFP+ ports (stride 4): Ethernet0,4,8,...,124
#   KVM VS maps port N in port_config.ini to kernel interface ethN (NIC-N).
#
#   Leaf_L3/L4 layout (32 data NICs):
#     NIC1-2:   host downlinks  (pos 1-2 = Ethernet0, Ethernet4)
#               NOTE: On physical hardware w/ QSFP+1 4x10G breakout, pos 2 would be
#               Ethernet1 (L3) or Ethernet2 (L4). KVM VS uses native → Ethernet4.
#     @28:      pad NIC3-30     (pos 3-30 = Ethernet8-Ethernet116, unused)
#     NIC31:    Spine_S2 uplink (pos 31 = Ethernet120 = QSFP+31)
#     NIC32:    Spine_S1 uplink (pos 32 = Ethernet124 = QSFP+32)
#     Total: 2 + 28 + 2 = 32 data NICs + 1 mgmt = 33 NICs per Arista leaf.
#
#   Border_Leaf1 layout (32 data NICs):
#     NIC1:     Exit_Router1    (pos 1 = Ethernet0 = QSFP+1, 4x10G breakout)
#     @4:       pad NIC2-5      (pos 2-5 = Ethernet4-Ethernet16, unused)
#     NIC6:     HostB12_1       (pos 6 = Ethernet20 = QSFP+6)
#     NIC7:     HostB12_2       (pos 7 = Ethernet24 = QSFP+7)
#     NIC8:     MonitorSrv      (pos 8 = Ethernet28 = QSFP+8)
#               NOTE: On physical hardware w/ QSFP+6 4x10G breakout, HostB12_2 would be
#               Ethernet21 (sub1) and MonitorSrv Ethernet22 (sub2). KVM VS uses native
#               port_config.ini positions → Ethernet24, Ethernet28 respectively.
#     @22:      pad NIC9-30     (pos 9-30 = Ethernet32-Ethernet116, unused)
#     NIC31:    Spine_S2 uplink (pos 31 = Ethernet120 = QSFP+31)
#     NIC32:    Spine_S1 uplink (pos 32 = Ethernet124 = QSFP+32)
#     Total: 1 + 4 + 1 + 1 + 1 + 22 + 2 = 32 data NICs + 1 mgmt = 33 NICs.
#
#   Border_Leaf2 layout (32 data NICs):
#     NIC1:     Exit_Router2    (pos 1 = Ethernet0 = QSFP+1, 4x10G breakout)
#     @4:       pad NIC2-5      (pos 2-5 = Ethernet4-Ethernet16, unused)
#     NIC6:     HostB12_1       (pos 6 = Ethernet20 = QSFP+6)
#     NIC7:     HostB12_2       (pos 7 = Ethernet24 = QSFP+7)
#     NIC8:     MonitorSrv      (pos 8 = Ethernet28 = QSFP+8)
#               NOTE: On physical hardware w/ QSFP+6 4x10G breakout, HostB12_2 would be
#               Ethernet21 (sub1) and MonitorSrv Ethernet22 (sub2). KVM VS uses native
#               port_config.ini positions → Ethernet24, Ethernet28 respectively.
#     @22:      pad NIC9-30     (pos 9-30 = Ethernet32-Ethernet116, unused)
#     NIC31:    Spine_S2 uplink (pos 31 = Ethernet120 = QSFP+31)
#     NIC32:    Spine_S1 uplink (pos 32 = Ethernet124 = QSFP+32)
#     Total: 1 + 4 + 1 + 1 + 1 + 22 + 2 = 32 data NICs + 1 mgmt = 33 NICs.
# Leaf_L3/L4 layout (32 data NICs):
#   NIC1:  Host34_1     (Ethernet0)
#   NIC2:  Host34_2     (Ethernet4)
#   NIC3:  MonitorSrv   (Ethernet8)
#   @27:   pad NIC4-30  (Ethernet12-Ethernet116, unused)
#   NIC31: Spine_S2     (Ethernet120)
#   NIC32: Spine_S1     (Ethernet124)
VM_BRIDGES[Leaf_L3]="br-H341-L3,br-H342-L3,br-MS-L3,@27,br-L3-S2,br-L3-S1"
VM_BRIDGES[Leaf_L4]="br-H341-L4,br-H342-L4,br-MS-L4,@27,br-L4-S2,br-L4-S1"
# Border_Leaf1/2 layout (32 data NICs):
#   NIC1:  Exit_Router1/2 primary  (Ethernet0 = br-BL1-ER1 / br-BL2-ER2)
#   NIC2:  Exit_Router2/1 failover (Ethernet4 = br-BL1-ER2 / br-BL2-ER1)
#   NIC3:  HostB12_1               (Ethernet8 = br-HB121-BL1/BL2)
#   NIC4:  HostB12_2               (Ethernet12 = br-HB122-BL1/BL2)
#   @26:   pad NIC5-30  (Ethernet16-Ethernet116, unused)
#   NIC31: Spine_S2     (Ethernet120)
#   NIC32: Spine_S1     (Ethernet124)
VM_BRIDGES[Border_Leaf1]="br-BL1-ER1,br-BL1-ER2,br-HB121-BL1,br-HB122-BL1,@26,br-BL1-S2,br-BL1-S1"
VM_BRIDGES[Border_Leaf2]="br-BL2-ER2,br-BL2-ER1,br-HB121-BL2,br-HB122-BL2,@26,br-BL2-S2,br-BL2-S1"
# Exit Router NIC layout (Ubuntu R630):
#   NIC0 (enp1s0): Management (br-mgmt / dc-mgmt)
#   NIC1 (enp2s0): Border-Leaf1 fabric (br-BL1-ER1 / br-BL1-ER2)
#   NIC2 (enp3s0): Border-Leaf2 fabric (br-BL2-ER1 / br-BL2-ER2)
#   NIC3 (enp4s0): WAN/ISP primary     (br-wan1 / br-wan2)
#   NIC4 (enp5s0): WAN/ISP secondary   (br-wan1 / br-wan2)
VM_BRIDGES[Exit_Router1]="br-BL1-ER1,br-BL2-ER1,br-wan1,br-wan1"
VM_BRIDGES[Exit_Router2]="br-BL1-ER2,br-BL2-ER2,br-wan2,br-wan2"
VM_BRIDGES[Host12_1]="br-H121-L1,br-H121-L2"
VM_BRIDGES[Host12_2]="br-H122-L1,br-H122-L2"
VM_BRIDGES[Host12_3]="br-H123-L1,br-H123-L2"
VM_BRIDGES[Host34_1]="br-H341-L3,br-H341-L4"
VM_BRIDGES[Host34_2]="br-H342-L3,br-H342-L4"
VM_BRIDGES[MonitorSrv]="br-MS-L3,br-MS-L4"
VM_BRIDGES[HostB12_1]="br-HB121-BL1,br-HB121-BL2"
VM_BRIDGES[HostB12_2]="br-HB122-BL1,br-HB122-BL2"

