validate_oob_isolation_policy() {
    [[ "$STRICT_OOB_ISOLATION" == "true" ]] || return 0

    local er1_br="${VM_BRIDGES[Exit_Router1]:-}"
    local er2_br="${VM_BRIDGES[Exit_Router2]:-}"

    # Validates presence within multi-homed comma-separated bridge configurations
    [[ "$er1_br" == *"br-BL1-ER1"* ]] || die "OOB policy violation: Exit_Router1 fabric bridge list must contain br-BL1-ER1 (found: '$er1_br')."
    [[ "$er2_br" == *"br-BL2-ER2"* ]] || die "OOB policy violation: Exit_Router2 fabric bridge list must contain br-BL2-ER2 (found: '$er2_br')."

    for br in "${FABRIC_BRIDGES[@]}"; do
        [[ "$br" == "$MGMT_NET_NAME" ]] && die "OOB policy violation: management network '$MGMT_NET_NAME' cannot appear in FABRIC_BRIDGES."
    done

    for vm in "${!VM_BRIDGES[@]}"; do
        local vm_bridges="${VM_BRIDGES[$vm]}"
        [[ "$vm_bridges" == *"$MGMT_NET_NAME"* ]] && die "OOB policy violation: VM '$vm' fabric map contains management network '$MGMT_NET_NAME'."
        [[ "$vm_bridges" == *"br-mgmt"* ]] && die "OOB policy violation: VM '$vm' fabric map contains br-mgmt."
    done

    ok "OOB policy validated: management network is isolated from fabric paths."
}

# ======================= UTILITY FUNCTIONS ==================================

# --- Target VM resolution ---
# Resolves user-supplied VM names/groups into a list of valid VM names
# Supports: individual names, groups (spines, leafs, border_leafs, servers, switches, all)
# Multiple VMs: comma-separated or space-separated
TARGET_VMS=()

resolve_targets() {
    local args=("$@")
    TARGET_VMS=()

    # If no targets specified, use all VMs
    if [[ ${#args[@]} -eq 0 ]]; then
        TARGET_VMS=("${VM_DEPLOY_ORDER[@]}")
        return 0
    fi

    for arg in "${args[@]}"; do
        # Split by comma if user passed "vm1,vm2,vm3"
        IFS=',' read -ra items <<< "$arg"
        for item in "${items[@]}"; do
            item=$(echo "$item" | xargs)  # trim whitespace
            case "${item,,}" in  # case-insensitive matching
                all)
                    TARGET_VMS=("${VM_DEPLOY_ORDER[@]}")
                    return 0
                    ;;
                spines)
                    TARGET_VMS+=(Spine_S1 Spine_S2)
                    ;;
                leafs|leaves)
                    TARGET_VMS+=(Leaf_L1 Leaf_L2 Leaf_L3 Leaf_L4)
                    ;;
                border_leafs|border-leafs|borders)
                    TARGET_VMS+=(Border_Leaf1 Border_Leaf2)
                    ;;
                switches|network)
                    TARGET_VMS+=(Spine_S1 Spine_S2 Leaf_L1 Leaf_L2 Leaf_L3 Leaf_L4 Border_Leaf1 Border_Leaf2)
                    ;;
                servers|hosts|compute)
                    TARGET_VMS+=(Host12_1 Host12_2 Host12_3 Host34_1 Host34_2 HostB12_1 HostB12_2 MonitorSrv)
                    ;;
                router|exitrouter|exit_router|chr|routers)
                    TARGET_VMS+=(Exit_Router1 Exit_Router2)
                    ;;
                *)
                    # Try exact match first
                    if [[ -n "${VM_TYPE[$item]+x}" ]]; then
                        TARGET_VMS+=("$item")
                    else
                        # Try case-insensitive match against known VMs
                        local matched=false
                        for vm in "${VM_DEPLOY_ORDER[@]}"; do
                            if [[ "${vm,,}" == "${item,,}" ]]; then
                                TARGET_VMS+=("$vm")
                                matched=true
                                break
                            fi
                        done
                        if ! $matched; then
                            err "Unknown VM or group: '$item'"
                            err "Valid VMs: ${VM_DEPLOY_ORDER[*]}"
                            err "Valid groups: all, spines, leafs, border_leafs, switches, servers, router"
                            return 1
                        fi
                    fi
                    ;;
            esac
        done
    done

    # Remove duplicates while preserving order
    local -A seen
    local unique=()
    for vm in "${TARGET_VMS[@]}"; do
        if [[ -z "${seen[$vm]+x}" ]]; then
            seen[$vm]=1
            unique+=("$vm")
        fi
    done
    TARGET_VMS=("${unique[@]}")
    return 0
}

gen_mac() {
    echo "${1}${2}" | md5sum | sed 's/^\(..\)\(..\)\(..\)\(..\)\(..\).*$/52:54:00:\1:\2:\3/'
}

check_integrity() {
    local file="$1"
    [[ ! -f "$file" || ! -s "$file" ]] && return 1
    case "${file##*.}" in
        qcow2) qemu-img check "$file" >/dev/null 2>&1 ;;
        gz)    gzip -t "$file" 2>/dev/null ;;
        zip)   unzip -t "$file" >/dev/null 2>&1 ;;
        img)   qemu-img info "$file" >/dev/null 2>&1 ;;
        *)     return 0 ;;
    esac
}

check_sha256() {
    local file="$1" expected="$2"
    [[ -z "$expected" ]] && return 0
    local actual
    actual=$(sha256sum "$file" | awk '{print $1}')
    if [[ "$actual" == "$expected" ]]; then
        ok "SHA256 verified: ${file##*/}"
        return 0
    else
        err "SHA256 MISMATCH for ${file##*/}"
        err "  Expected: $expected"
        err "  Got:      $actual"
        return 1
    fi
}

download_safe() {
    # Proxy-aware download with wget/curl fallback and retry.
    # Respects PROXY_MODE: corporate/custom (use proxy), direct (no proxy).
    local url="$1" dest="$2" desc="${3:-file}"
    local attempt=1 max_retries=3

    [[ -f "$dest" ]] && check_integrity "$dest" && { ok "$desc already present."; return 0; }
    [[ -f "$dest" ]] && { warn "Removing corrupt $desc..."; rm -f "$dest"; }

    # Build proxy arguments based on PROXY_MODE
    local wget_proxy_args="" curl_proxy_args=""
    if [[ "$PROXY_MODE" == "direct" ]]; then
        wget_proxy_args="--no-proxy"
        curl_proxy_args="--noproxy '*'"
    else
        wget_proxy_args="-e use_proxy=yes -e http_proxy=${HTTP_PROXY:-} -e https_proxy=${HTTPS_PROXY:-}"
        curl_proxy_args="-x ${HTTP_PROXY:-}"
    fi

    while [[ $attempt -le $max_retries ]]; do
        log "Downloading $desc (attempt $attempt/$max_retries) [proxy=$PROXY_MODE]..."
        if command -v wget &>/dev/null; then
            if wget $wget_proxy_args \
                    --no-check-certificate -q --show-progress --content-disposition \
                    --timeout=120 --tries=2 -O "$dest" "$url" 2>&1; then
                check_integrity "$dest" && { ok "$desc downloaded."; return 0; }
            fi
        elif command -v curl &>/dev/null; then
            if eval curl $curl_proxy_args -L --insecure -o \"\$dest\" --connect-timeout 60 \"\$url\" 2>&1; then
                check_integrity "$dest" && { ok "$desc downloaded."; return 0; }
            fi
        else
            die "Neither wget nor curl available."
        fi
        warn "Attempt $attempt failed for $desc — retrying..."
        rm -f "$dest"
        attempt=$((attempt + 1))
        sleep 5
    done
    err "Failed to download $desc after $max_retries attempts."
    return 1
}

check_and_install() {
    local cmd="$1" pkg="${2:-$1}"
    if ! command -v "$cmd" &>/dev/null; then
        log "Installing $pkg..."
        sudo apt-get install -y -qq "$pkg" 2>&1 | tail -1
    fi
}

# Remove stale vnet ports from OVS bridges (devices that no longer exist)
# This prevents "port vnetX is actually attached to bridge br-Y" errors
# when libvirt reuses vnet names for new VMs.
clean_stale_ovs_ports() {
    local cleaned=0
    local br port
    for br in $(sudo ovs-vsctl list-br 2>/dev/null || true); do
        for port in $(sudo ovs-vsctl list-ports "$br" 2>/dev/null || true); do
            # Only clean vnet* ports (libvirt-managed tap devices)
            [[ "$port" == vnet* ]] || continue
            # If the network device no longer exists, remove the stale port
            if [[ ! -e "/sys/class/net/${port}" ]]; then
                sudo ovs-vsctl --if-exists del-port "$br" "$port" 2>/dev/null || true
                cleaned=$((cleaned + 1))
            fi
        done
    done
    if [[ $cleaned -gt 0 ]]; then
        log "Cleaned $cleaned stale vnet port(s) from OVS bridges."
    fi
    return 0
}

force_delete_vm() {
    local name="$1"
    if sudo virsh dominfo "$name" &>/dev/null; then
        log "Force-deleting existing VM: $name"
        sudo virsh destroy "$name" 2>/dev/null || true
        # DO NOT use --remove-all-storage — it deletes shared backing images!
        sudo virsh undefine "$name" 2>/dev/null || true
        sudo rm -f "$DISK_DIR/${name}.qcow2" "$DISK_DIR/${name}.img"
        sudo rm -f "$CLOUD_INIT_DIR/${name}-cidata.iso"
        # Clean up any stale vnet ports left behind by the destroyed VM
        clean_stale_ovs_ports
    fi
}

# ======================= PHASE 0: PREREQUISITES =============================
phase0_setup() {
    header "PHASE 0: Prerequisites & Dependencies"
    mkdir -p "$IMG_DIR" "$TMP_DIR" "$DISK_DIR" "$CLOUD_INIT_DIR" "$PROJECT_ROOT"

    # --- Install required packages (only missing ones) ---
    local REQUIRED_PKGS=(
        libvirt-daemon-system libvirt-clients virtinst
        bridge-utils openvswitch-switch cloud-image-utils
        qemu-utils wget unzip openssh-client jq sshpass curl
        genisoimage
    )
    local to_install=()
    # qemu-kvm is transitional on Ubuntu 24.04; check for actual binary instead
    if ! command -v qemu-system-x86_64 &>/dev/null; then
        to_install+=("qemu-kvm")
    fi
    for pkg in "${REQUIRED_PKGS[@]}"; do
        if ! dpkg -l "$pkg" 2>/dev/null | grep -q "^ii"; then
            to_install+=("$pkg")
        fi
    done
    if [[ ${#to_install[@]} -gt 0 ]]; then
        log "Installing: ${to_install[*]}"
        sudo apt-get update -qq
        sudo apt-get install -y -qq "${to_install[@]}" 2>&1 | tail -3
        ok "Packages installed."
    else
        ok "All required packages present."
    fi

    # --- KVM check ---
    if [[ ! -e /dev/kvm ]]; then
        warn "/dev/kvm not found. Ensure .wslconfig has nestedVirtualization=true"
        die "Cannot continue without /dev/kvm."
    fi
    sudo chmod 666 /dev/kvm 2>/dev/null || true
    ok "KVM accessible."

    # --- Libvirt ---
    sudo service libvirtd start 2>/dev/null || sudo systemctl start libvirtd 2>/dev/null || true
    sudo service virtlogd start 2>/dev/null || sudo systemctl start virtlogd 2>/dev/null || true
    sleep 1
    sudo virsh list --all >/dev/null 2>&1 || die "Libvirt not responding."
    ok "Libvirt running."

    # --- Open vSwitch ---
    sudo service openvswitch-switch start 2>/dev/null || sudo systemctl start openvswitch-switch 2>/dev/null || true
    sleep 1
    sudo ovs-vsctl show >/dev/null 2>&1 || die "Open vSwitch not responding."
    ok "Open vSwitch running."

    # --- Permissions (user-centric approach from v8+) ---
    sudo chown -R "$USER":"$USER" "$IMG_DIR" "$TMP_DIR" "$DISK_DIR" "$CLOUD_INIT_DIR" 2>/dev/null || true
    chmod -R u+rwX "$IMG_DIR" "$TMP_DIR" "$DISK_DIR" "$CLOUD_INIT_DIR" 2>/dev/null || true

    # --- Ensure libvirt-qemu can traverse parent directories to reach disk/cloud-init ---
    # libvirt-qemu (uid:64055) needs execute (search) permission on every directory
    # in the path from / to $LAB_ROOT. Without this, virt-install fails with:
    #   "Cannot access storage file ... Permission denied"
    local dir="$LAB_ROOT"
    while [[ "$dir" != "/" ]]; do
        local perms
        perms=$(stat -c '%a' "$dir" 2>/dev/null)
        if [[ "${perms: -1}" -lt 1 ]]; then
            log "    Granting traverse (o+x) on $dir for libvirt-qemu access"
            sudo chmod o+x "$dir"
        fi
        dir=$(dirname "$dir")
    done
    # Also ensure the parent of LAB_ROOT itself is traversable (e.g., /root)
    local lab_parent
    lab_parent=$(dirname "$LAB_ROOT")
    if [[ "$lab_parent" == "/root" ]] || [[ "$lab_parent" == "$HOME" && "$HOME" == "/root" ]]; then
        local root_perms
        root_perms=$(stat -c '%a' /root 2>/dev/null)
        if [[ "${root_perms: -1}" -lt 1 ]]; then
            log "    Granting traverse (o+x) on /root for libvirt-qemu access"
            sudo chmod o+x /root
        fi
    fi
    # Ensure LAB_ROOT subdirs are world-readable for qemu
    sudo chmod -R o+rX "$DISK_DIR" "$CLOUD_INIT_DIR" 2>/dev/null || true
    ok "Permissions configured."
}

# ======================= IMAGE TYPE DETECTION ================================
# Determine which image types (sonic/ubuntu/chr) are needed based on TARGET_VMS.
# Sets global arrays: NEED_SONIC, NEED_UBUNTU, NEED_CHR (true/false)
compute_needed_image_types() {
    NEED_SONIC=false
    NEED_UBUNTU=false
    NEED_CHR=false
    for vm in "${TARGET_VMS[@]}"; do
        case "${VM_TYPE[$vm]}" in
            sonic)  NEED_SONIC=true ;;
            ubuntu) NEED_UBUNTU=true ;;
            chr)    NEED_CHR=true ;;
        esac
    done
}

# Check if a processed base image already exists and is valid in IMG_DIR.
# Returns 0 if usable, 1 if download+process is needed.
image_ready() {
    local img_file="$1"
    [[ -f "$img_file" ]] && check_integrity "$img_file" && return 0
    return 1
}

# ======================= PHASE 1: DOWNLOAD TO TMP ===========================
phase1_download() {
    header "PHASE 1: Download Required Images to TMP"

    compute_needed_image_types

    local skipped=0 downloaded=0

    # --- SONiC ---
    if [[ "$NEED_SONIC" == "true" ]]; then
        local sonic_img="$IMG_DIR/sonic-vs.qcow2"
        [[ "$SONIC_DISK_FORMAT" != "qcow2" ]] && sonic_img="$IMG_DIR/sonic-vs.img"
        if image_ready "$sonic_img"; then
            ok "SONiC VS (202405) — processed image exists, skipping download."
            skipped=$((skipped + 1))
        else
            download_safe "$SONIC_URL" "$TMP_DIR/sonic-vs.img.gz" "SONiC VS (202405)" || \
                die "Cannot proceed without SONiC image."
            downloaded=$((downloaded + 1))
        fi
    else
        log "SONiC image not needed for target VMs — skipped."
        skipped=$((skipped + 1))
    fi

    # --- Ubuntu ---
    if [[ "$NEED_UBUNTU" == "true" ]]; then
        if image_ready "$IMG_DIR/ubuntu-cloud.qcow2"; then
            ok "Ubuntu Noble 24.04 — processed image exists, skipping download."
            skipped=$((skipped + 1))
        else
            download_safe "$UBUNTU_URL" "$TMP_DIR/ubuntu_base.img" "Ubuntu Noble 24.04" || \
                die "Cannot proceed without Ubuntu image."
            downloaded=$((downloaded + 1))
        fi
    else
        log "Ubuntu image not needed for target VMs — skipped."
        skipped=$((skipped + 1))
    fi

    # --- MikroTik CHR ---
    if [[ "$NEED_CHR" == "true" ]]; then
        if image_ready "$IMG_DIR/chr.qcow2"; then
            ok "MikroTik CHR 7.16 — processed image exists, skipping download."
            skipped=$((skipped + 1))
        else
            download_safe "$CHR_URL" "$TMP_DIR/chr.zip" "MikroTik CHR 7.16" || \
                die "Cannot proceed without CHR image."
            # SHA256 verification for CHR
            check_sha256 "$TMP_DIR/chr.zip" "$CHR_SHA256" || \
                die "CHR image SHA256 mismatch — possible corruption or tampering."
            downloaded=$((downloaded + 1))
        fi
    else
        log "MikroTik CHR image not needed for target VMs — skipped."
        skipped=$((skipped + 1))
    fi

    ok "Image downloads: $downloaded fetched, $skipped skipped."
}

# ======================= PHASE 2: VERIFY & PROCESS IMAGES ===================
phase2_process() {
    header "PHASE 2: Verify Integrity & Process Images"

    local processed=0 skipped=0

    # --- SONiC ---
    local sonic_img="$IMG_DIR/sonic-vs.qcow2"
    [[ "$SONIC_DISK_FORMAT" != "qcow2" ]] && sonic_img="$IMG_DIR/sonic-vs.img"

    if [[ "$NEED_SONIC" == "true" ]] && ! image_ready "$sonic_img"; then
        log "Processing SONiC image..."
        check_integrity "$TMP_DIR/sonic-vs.img.gz" || die "sonic-vs.img.gz is corrupt."
        gunzip -kf "$TMP_DIR/sonic-vs.img.gz"  # -k keeps the .gz

        # Detect actual format (SONiC VS .img is qcow2 despite the name)
        local sonic_src_fmt
        sonic_src_fmt=$(qemu-img info --output=json "$TMP_DIR/sonic-vs.img" | jq -r '.format')
        log "SONiC source format detected: $sonic_src_fmt"

        if [[ "$SONIC_DISK_FORMAT" == "qcow2" ]]; then
            if [[ "$sonic_src_fmt" == "qcow2" ]]; then
                cp "$TMP_DIR/sonic-vs.img" "$IMG_DIR/sonic-vs.qcow2"
            else
                sudo qemu-img convert -f "$sonic_src_fmt" -O qcow2 "$TMP_DIR/sonic-vs.img" "$IMG_DIR/sonic-vs.qcow2"
            fi
        else
            if [[ "$sonic_src_fmt" == "raw" ]]; then
                cp "$TMP_DIR/sonic-vs.img" "$IMG_DIR/sonic-vs.img"
            else
                sudo qemu-img convert -f "$sonic_src_fmt" -O raw "$TMP_DIR/sonic-vs.img" "$IMG_DIR/sonic-vs.img"
            fi
        fi
        rm -f "$TMP_DIR/sonic-vs.img"
        ok "SONiC processed (format: $SONIC_DISK_FORMAT, source was: $sonic_src_fmt)."
        processed=$((processed + 1))
    else
        [[ "$NEED_SONIC" == "true" ]] && ok "SONiC image already processed — skipped."
        skipped=$((skipped + 1))
    fi

    # --- Ubuntu ---
    if [[ "$NEED_UBUNTU" == "true" ]] && ! image_ready "$IMG_DIR/ubuntu-cloud.qcow2"; then
        log "Processing Ubuntu image..."
        check_integrity "$TMP_DIR/ubuntu_base.img" || die "Ubuntu image is corrupt."
        sudo qemu-img convert -f qcow2 -O qcow2 "$TMP_DIR/ubuntu_base.img" "$IMG_DIR/ubuntu-cloud.qcow2"
        ok "Ubuntu processed."
        processed=$((processed + 1))
    else
        [[ "$NEED_UBUNTU" == "true" ]] && ok "Ubuntu image already processed — skipped."
        skipped=$((skipped + 1))
    fi

    # --- MikroTik CHR ---
    if [[ "$NEED_CHR" == "true" ]] && ! image_ready "$IMG_DIR/chr.qcow2"; then
        log "Processing MikroTik CHR image..."
        check_integrity "$TMP_DIR/chr.zip" || die "CHR zip is corrupt."
        unzip -qo "$TMP_DIR/chr.zip" -d "$TMP_DIR"
        local raw
        raw=$(find "$TMP_DIR" -maxdepth 1 -name "chr-*.img" | head -1)
        [[ -z "$raw" ]] && die "No chr-*.img found in zip."
        sudo qemu-img convert -f raw -O qcow2 "$raw" "$IMG_DIR/chr.qcow2"
        rm -f "$raw"
        ok "CHR processed."
        processed=$((processed + 1))
    else
        [[ "$NEED_CHR" == "true" ]] && ok "MikroTik CHR image already processed — skipped."
        skipped=$((skipped + 1))
    fi

    # --- Post-conversion integrity verification (only for newly processed) ---
    if [[ $processed -gt 0 ]]; then
        log "Verifying processed images..."
        if [[ "$NEED_SONIC" == "true" ]]; then
            check_integrity "$sonic_img" || die "SONiC image failed integrity check."
        fi
        if [[ "$NEED_UBUNTU" == "true" ]]; then
            check_integrity "$IMG_DIR/ubuntu-cloud.qcow2" || die "Ubuntu qcow2 failed integrity check."
        fi
        if [[ "$NEED_CHR" == "true" ]]; then
            check_integrity "$IMG_DIR/chr.qcow2" || die "CHR qcow2 failed integrity check."
        fi
        # Fix permissions for libvirt
        sudo chmod -R o+rX "$IMG_DIR"
    fi

    ok "Image processing: $processed converted, $skipped already ready."
}

# ======================= PHASE 3: NETWORKING ================================
phase3_networks() {
    header "PHASE 3: Create Management & Fabric Networks"

    validate_oob_isolation_policy

    # --- Management network (libvirt NAT) ---
    # Helper: (re)create the management network XML from scratch
    _define_mgmt_net() {
        local net_xml="$TMP_DIR/net-mgmt.xml"
        cat > "$net_xml" <<XMLEOF
<network>
  <name>${MGMT_NET_NAME}</name>
  <forward mode='nat'/>
  <bridge name='br-mgmt' stp='on' delay='0'/>
  <ip address='${MGMT_NET_GW}' netmask='255.255.255.0'>
    <dhcp>
      <range start='${MGMT_DHCP_START}' end='${MGMT_DHCP_END}'/>
XMLEOF
        for vm in "${!VM_MGMT_IP[@]}"; do
            local mac
            mac=$(gen_mac "$vm" "mgmt")
            echo "      <host mac='${mac}' name='${vm}' ip='${VM_MGMT_IP[$vm]}'/>" >> "$net_xml"
        done
        cat >> "$net_xml" <<XMLEOF
    </dhcp>
  </ip>
</network>
XMLEOF
        sudo virsh net-define "$net_xml"
        # Unconditionally remove any stale br-mgmt device before starting the network.
        # virsh net-start creates br-mgmt — if it already exists (stale), start fails.
        # No conditional check — just force-remove; if it doesn't exist, commands harmlessly fail.
        # Could be an OVS bridge, a Linux bridge, or an OVS internal port — try all methods.
        sudo ovs-vsctl --if-exists del-br br-mgmt 2>/dev/null || true
        sudo ovs-vsctl --if-exists del-port br-mgmt 2>/dev/null || true
        sudo ip link set br-mgmt down 2>/dev/null || true
        sudo ip link delete dev br-mgmt 2>/dev/null || true
        sudo brctl delbr br-mgmt 2>/dev/null || true
        sudo virsh net-start "$MGMT_NET_NAME"
        sudo virsh net-autostart "$MGMT_NET_NAME"
    }

    if ! sudo virsh net-info "$MGMT_NET_NAME" &>/dev/null; then
        log "Defining management network ($MGMT_NET_NAME)..."
        _define_mgmt_net
        ok "Management network created."
    else
        # Try to start the existing network; if it fails, the definition is stale — nuke and recreate
        if ! sudo virsh net-start "$MGMT_NET_NAME" 2>/dev/null; then
            # Check if it's already active (net-start fails on an already-running network too)
            if ! sudo virsh net-info "$MGMT_NET_NAME" 2>/dev/null | grep -q "Active:.*yes"; then
                warn "Management network '$MGMT_NET_NAME' exists but cannot start (stale definition). Recreating..."
                # Running VMs have tap/vnet interfaces enslaved to br-mgmt, which prevents
                # bridge deletion. Since the mgmt network is broken, those VMs are useless.
                # Destroy ALL lab VMs first so their tap interfaces are released.
                warn "Destroying all lab VMs (their mgmt NICs hold br-mgmt open)..."
                for vm in "${VM_DEPLOY_ORDER[@]}"; do
                    sudo virsh destroy "$vm" 2>/dev/null || true
                    sudo virsh undefine "$vm" 2>/dev/null || true
                done
                # Also catch orphans not in VM_DEPLOY_ORDER
                local stale_doms
                stale_doms=$(sudo virsh list --all --name 2>/dev/null | grep -E '^(Spine_|Leaf_|Border_Leaf|Exit_Router|Host|MonitorSrv)' || true)
                for orphan in $stale_doms; do
                    sudo virsh destroy "$orphan" 2>/dev/null || true
                    sudo virsh undefine "$orphan" 2>/dev/null || true
                done
                # Now tear down the stale network definition
                sudo virsh net-destroy "$MGMT_NET_NAME" 2>/dev/null || true
                sudo virsh net-undefine "$MGMT_NET_NAME" 2>/dev/null || true
                # Kill any orphan dnsmasq bound to this bridge (use [] trick to avoid self-match)
                sudo pkill -9 -f "[d]nsmasq.*br-mgmt" 2>/dev/null || true
                # Remove the stale bridge device — could be OVS, Linux bridge, or OVS port
                sudo ovs-vsctl --if-exists del-br br-mgmt 2>/dev/null || true
                sudo ovs-vsctl --if-exists del-port br-mgmt 2>/dev/null || true
                sudo ip link set br-mgmt down 2>/dev/null || true
                sudo ip link delete dev br-mgmt 2>/dev/null || true
                sudo brctl delbr br-mgmt 2>/dev/null || true
                # Also clean up disks/ISOs since VMs were destroyed
                sudo rm -rf "$DISK_DIR"/* "$CLOUD_INIT_DIR"/*
                _define_mgmt_net
                ok "Management network recreated from scratch (all VMs will be redeployed)."
            fi
        fi
        # Verify the network is actually active before proceeding
        if ! sudo virsh net-info "$MGMT_NET_NAME" 2>/dev/null | grep -q "Active:.*yes"; then
            die "Management network '$MGMT_NET_NAME' is not active after start attempt. Manual intervention required."
        fi
        # Sync DHCP host reservations (MACs may have changed since network was created)
        log "Syncing DHCP host reservations on existing network..."
        for vm in "${!VM_MGMT_IP[@]}"; do
            local mac
            mac=$(gen_mac "$vm" "mgmt")
            # Remove old entry (ignore errors if not present), then add current one
            sudo virsh net-update "$MGMT_NET_NAME" delete ip-dhcp-host \
                "<host name='${vm}'/>" --live --config 2>/dev/null || true
            sudo virsh net-update "$MGMT_NET_NAME" add ip-dhcp-host \
                "<host mac='${mac}' name='${vm}' ip='${VM_MGMT_IP[$vm]}'/>" \
                --live --config 2>/dev/null || true
        done
        ok "Management network active (DHCP reservations synced)."
    fi

    # --- Fabric OVS bridges ---
    log "Creating ${#FABRIC_BRIDGES[@]} OVS fabric bridges..."
    local created=0
    for br in "${FABRIC_BRIDGES[@]}"; do
        if ! sudo ovs-vsctl br-exists "$br" 2>/dev/null; then
            sudo ovs-vsctl add-br "$br"
            created=$((created + 1))
        fi
        # Enable LLDP/BPDUs forwarding — OVS drops IEEE reserved multicast
        # (01:80:c2:00:00:0e) by default, which blocks LLDP between SONiC VMs
        sudo ovs-vsctl set bridge "$br" other-config:forward-bpdu=true 2>/dev/null || true
    done
    ok "Fabric bridges: $created new, $((${#FABRIC_BRIDGES[@]} - created)) existing (forward-bpdu enabled)."

    # --- Libvirt network definitions for OVS bridges ---
    for br in "${FABRIC_BRIDGES[@]}"; do
        local need_define=false
        if sudo virsh net-info "$br" &>/dev/null; then
            # Network definition exists — ensure it's active
            if ! sudo virsh net-info "$br" 2>/dev/null | grep -q "Active:.*yes"; then
                # Try to start; if it fails, the definition is stale
                if ! sudo virsh net-start "$br" 2>/dev/null; then
                    warn "Libvirt network '$br' stale — destroying and recreating."
                    sudo virsh net-destroy "$br" 2>/dev/null || true
                    sudo virsh net-undefine "$br" 2>/dev/null || true
                    need_define=true
                fi
            fi
        else
            need_define=true
        fi
        if $need_define; then
            cat > "$TMP_DIR/net-${br}.xml" <<BXML
<network>
  <name>${br}</name>
  <forward mode='bridge'/>
  <bridge name='${br}'/>
  <virtualport type='openvswitch'/>
</network>
BXML
            sudo virsh net-define "$TMP_DIR/net-${br}.xml"
            sudo virsh net-start "$br"
            sudo virsh net-autostart "$br"
        fi
    done
    ok "All libvirt OVS networks defined and active."

    # --- WAN/ISP bridge hypervisor-side gateway for exit router internet ---
    # br-wan1: Exit_Router1 WAN (192.168.1.0/24, hypervisor is .1 gateway + NAT)
    # br-wan2: Exit_Router2 WAN (192.168.2.0/24, hypervisor is .1 gateway + NAT)
    log "Configuring WAN/ISP bridge gateways for exit router internet access..."
    for wan_idx in 1 2; do
        local wan_br="br-wan${wan_idx}"
        local wan_gw="192.168.${wan_idx}.1"
        sudo ip addr flush dev "$wan_br" 2>/dev/null || true
        sudo ip addr add "${wan_gw}/24" dev "$wan_br" 2>/dev/null || true
        sudo ip link set dev "$wan_br" up
        # NAT masquerade so exit routers can reach the internet via hypervisor
        if ! sudo iptables -t nat -C POSTROUTING -s "192.168.${wan_idx}.0/24" ! -d "192.168.${wan_idx}.0/24" -j MASQUERADE 2>/dev/null; then
            sudo iptables -t nat -A POSTROUTING -s "192.168.${wan_idx}.0/24" ! -d "192.168.${wan_idx}.0/24" -j MASQUERADE
        fi
    done
    ok "WAN bridges configured (192.168.1.1/24 on br-wan1, 192.168.2.1/24 on br-wan2)."

    # --- Clean stale vnet ports from previous failed/destroyed VMs ---
    clean_stale_ovs_ports
}

# ======================= PHASE 4: VM DEPLOYMENT =============================

create_cloud_init_iso() {
    local vm_name="$1" user="$2" pass="$3"
    local iso="$CLOUD_INIT_DIR/${vm_name}-cidata.iso"
    [[ -f "$iso" ]] && return 0

    # Cloud-init requires files named exactly "user-data" and "meta-data"
    # Use a per-VM temp directory to avoid collisions during parallel builds
    local ci_tmp="$TMP_DIR/ci-${vm_name}"
    mkdir -p "$ci_tmp"
    local md="$ci_tmp/meta-data"
    local ud="$ci_tmp/user-data"

    cat > "$md" <<EOF
instance-id: ${vm_name}
local-hostname: ${vm_name}
EOF

#     cat > "$ud" <<EOF
# #cloud-config
# hostname: ${vm_name}
# manage_etc_hosts: true
# users:
#   - name: ${user}
#     sudo: ALL=(ALL) NOPASSWD:ALL
#     lock_passwd: false
#     plain_text_passwd: '${pass}'
#     shell: /bin/bash
# ssh_pwauth: true
# disable_root: false
# chpasswd:
#   expire: false
#   list: |
#     ${user}:${pass}
# package_update: false

# # ---- Disk growth: expand root partition to fill the virtual disk ----
# growpart:
#   mode: auto
#   devices: ['/']
#   ignore_growroot_disabled: false
# resize_rootfs: true

# # ---- Disable cloud-init network config AFTER first boot ----
# # Without this, cloud-init overwrites /etc/netplan/ on every reboot,
# # destroying Day0/Day1 netplan files (10-loopback.yaml, 20-fabric.yaml).
# write_files:
#   - path: /etc/cloud/cloud.cfg.d/99-disable-network-config.cfg
#     content: |
#       network: {config: disabled}
#     permissions: '0644'

# runcmd:
#   - systemctl enable serial-getty@ttyS0.service || true
#   # Disable cloud-init from re-running on subsequent boots
#   - touch /etc/cloud/cloud-init.disabled
#   - echo "Cloud-init complete for ${vm_name}" > /var/log/cloud-init-done
# EOF
 cat > "$ud" <<EOF
#cloud-config
hostname: ${vm_name}
manage_etc_hosts: true
users:
 - name: ${user}
   sudo: ALL=(ALL) NOPASSWD:ALL
   lock_passwd: false
   plain_text_passwd: '${pass}'
   shell: /bin/bash
ssh_pwauth: true
disable_root: false
chpasswd:
 expire: false
 list: |
   ${user}:${pass}
package_update: false
growpart:
 mode: auto
 devices: ['/']
 ignore_growroot_disabled: false
resize_rootfs: true
write_files:
 - path: /etc/cloud/cloud.cfg.d/99-disable-network-config.cfg
   content: |
     network: {config: disabled}
   permissions: '0644'
EOF

  if [[ "$vm_name" == "Exit_Router1" || "$vm_name" == "Exit_Router2" ]]; then
    local clean_slot="41"
    local wan_gw="192.168.1.1"
    local wan_ip="192.168.1.50/24"
    local mgmt_ip="${VM_MGMT_IP[$vm_name]}"
    if [[ "$vm_name" == "Exit_Router2" ]]; then
      clean_slot="42"
      wan_gw="192.168.2.1"
      wan_ip="192.168.2.50/24"
    fi

    # Exit Router uses write_files to pre-stage all config files, avoiding
    # heredoc-inside-YAML indentation bugs. NIC mapping:
    #   enp1s0 = mgmt (VRF mgmt-vrf)
    #   enp2s0 = Border-Leaf1 fabric (VRF Vrf_Transit, BGP unnumbered)
    #   enp3s0 = Border-Leaf2 fabric (VRF Vrf_Transit, BGP unnumbered)
    #   enp4s0 = WAN/ISP primary (VRF Vrf_Transit, NAT outbound)
    #   enp5s0 = WAN/ISP secondary (optional backup)
    cat >> "$ud" <<UDROUTEREOF
 - path: /etc/netplan/01-router-net.yaml
   permissions: '0600'
   content: |
     network:
       version: 2
       renderer: networkd
       vrfs:
         mgmt-vrf:
           table: 1000
           interfaces: [enp1s0]
           routing-policy:
             - from: 192.168.99.0/24
               table: 1000
         Vrf_Transit:
           table: 2000
           interfaces: [enp2s0, enp3s0, enp4s0, enp5s0]
       ethernets:
         enp1s0:
           dhcp4: false
           addresses: [${mgmt_ip}/24]
           routes:
             - to: 10.10.1.0/24
               via: 10.10.1.1
               table: 1000
         enp4s0:
           dhcp4: false
           addresses: [${wan_ip}]
           routes:
             - to: default
               via: ${wan_gw}
               metric: 100
         enp5s0: { dhcp4: false, optional: true }
         enp2s0: { dhcp4: false, ipv6-privacy: false }
         enp3s0: { dhcp4: false, ipv6-privacy: false }
       loopbacks:
         lo:
           addresses: [10.1.12.${clean_slot}/32]
 - path: /etc/wireguard/wg0.conf
   permissions: '0600'
   content: |
     [Interface]
     PrivateKey = SERVER_PRIVATE_KEY_PLACEHOLDER
     ListenPort = 51820
     Address = 192.168.99.1/24
     [Peer]
     PublicKey = ADMIN_LAPTOP_PUBLIC_KEY_PLACEHOLDER
     AllowedIPs = 192.168.99.100/32, 10.10.0.0/16
 - path: /etc/frr/frr.conf
   permissions: '0640'
   owner: frr:frr
   content: |
     frr version 8.x
     !
     router bgp 4200000000 vrf Vrf_Transit
      bgp router-id 10.1.12.${clean_slot}
      no bgp default ipv4-unicast
      bgp bestpath as-path multipath-relax
      !
      neighbor enp2s0 interface remote-as 4200000001
      neighbor enp3s0 interface remote-as 4200000002
      !
      address-family ipv4 unicast
       neighbor enp2s0 activate
       neighbor enp2s0 capability extended-nexthop
       neighbor enp3s0 activate
       neighbor enp3s0 capability extended-nexthop
       !
       default-originate
       redistribute kernel
       maximum-paths 64
      exit-address-family
     !
 - path: /usr/local/bin/router-bootstrap.sh
   permissions: '0755'
   content: |
     #!/bin/bash
     set -e
     apt-get update && apt-get install -y wireguard frr frr-pythontools iptables
     sed -i 's/bgpd=no/bgpd=yes/g' /etc/frr/daemons
     rm -f /etc/netplan/50-cloud-init.yaml
     netplan generate && netplan apply
     systemctl enable wg-quick@wg0 && systemctl start wg-quick@wg0
     ip route add 192.168.99.0/24 dev wg0 table 1000 || true
     systemctl restart frr
     iptables -t nat -A POSTROUTING -o enp4s0 -j MASQUERADE
runcmd:
 - systemctl enable serial-getty@ttyS0.service || true
 - /usr/local/bin/router-bootstrap.sh
 - touch /etc/cloud/cloud-init.disabled
UDROUTEREOF
  elif [[ "$vm_name" =~ ^Host || "$vm_name" == "MonitorSrv" ]]; then
    local target_ip="${VM_MGMT_IP[$vm_name]}"

    # Use write_files to pre-stage netplan configs and bootstrap script.
    # This avoids broken heredocs inside bash -c strings.
    cat >> "$ud" <<UDHOSTEOF
 - path: /etc/netplan/00-oob-management.yaml
   permissions: '0600'
   content: |
     network:
       version: 2
       renderer: networkd
       ethernets:
         mgtport:
           match:
             name: enp1s0
           set-name: mgtport
           dhcp4: false
           addresses: [${target_ip}/24]
           routes:
             - to: default
               via: 10.10.1.1
               metric: 10
 - path: /etc/netplan/.00-vrf-staged.yaml
   permissions: '0600'
   content: |
     network:
       version: 2
       renderer: networkd
       vrfs:
         mgmt-vrf:
           table: 1000
           interfaces: [mgtport]
       ethernets:
         mgtport:
           match:
             name: enp1s0
           set-name: mgtport
           dhcp4: false
           addresses: [${target_ip}/24]
           routes:
             - to: 10.10.1.0/24
               via: 10.10.1.1
               metric: 10
               table: 1000
         enp2s0: { dhcp4: false, optional: true }
         enp3s0: { dhcp4: false, optional: true }
 - path: /usr/local/bin/vrf-bootstrap.sh
   permissions: '0755'
   content: |
     #!/bin/bash
     set -e
     until ping -c 1 -W 1 10.10.1.1 &>/dev/null; do sleep 2; done
     apt-get update && apt-get install -y linux-modules-extra-generic
     modprobe vrf
     echo 'vrf' >> /etc/modules
     mv /etc/netplan/.00-vrf-staged.yaml /etc/netplan/00-oob-management.yaml
     netplan generate && netplan apply
     systemctl stop systemd-resolved || true
     systemctl disable systemd-resolved || true
     rm -f /etc/resolv.conf
     echo 'nameserver 8.8.8.8' > /etc/resolv.conf
     echo 'nameserver 1.1.1.1' >> /etc/resolv.conf
     chattr +i /etc/resolv.conf || true
     ip route add default via 10.10.1.1 dev mgtport metric 20 || true
     echo '${user} ALL=(ALL) NOPASSWD:ALL' > /etc/sudoers.d/90-cloud-init-users
     chmod 0440 /etc/sudoers.d/90-cloud-init-users
runcmd:
 - systemctl enable serial-getty@ttyS0.service || true
 - rm -f /etc/netplan/50-cloud-init.yaml
 - netplan generate && netplan apply
 - nohup /usr/local/bin/vrf-bootstrap.sh >/var/log/vrf-bootstrap.log 2>&1 &
 - touch /etc/cloud/cloud-init.disabled
UDHOSTEOF

  else
    cat >> "$ud" <<EOF
runcmd:
 - systemctl enable serial-getty@ttyS0.service || true
 - touch /etc/cloud/cloud-init.disabled
 - echo "Cloud-init complete for ${vm_name}" > /var/log/cloud-init-done
EOF
  fi

    # Network-config: only configure mgmt NIC via DHCP using match by MAC.
    # Without this, cloud-init waits for ALL NICs to come up, blocking boot
    # when fabric NICs have no DHCP server.
    # Note: Ubuntu Noble cloud images use predictable names (enp1s0, enp2s0...)
    # so we match by MAC address for portability.
    local nc="$ci_tmp/network-config"
    local mgmt_mac
    mgmt_mac=$(gen_mac "$vm_name" "mgmt")
    cat > "$nc" <<EOF
version: 2
ethernets:
  mgmt:
    match:
      macaddress: "${mgmt_mac}"
    dhcp4: true
EOF

    genisoimage -output "$iso" -volid cidata -joliet -rock "$ud" "$md" "$nc" 2>/dev/null
    rm -rf "$ci_tmp"
    sudo chmod o+r "$iso"
}

deploy_single_vm() {
    local name="$1"
    local type="${VM_TYPE[$name]}"
    local ram="${VM_RAM[$name]}"
    local vcpu="${VM_VCPU[$name]}"
    local bridges="${VM_BRIDGES[$name]:-}"
    local user="${VM_USER[$type]}"
    local pass="${VM_PASS[$type]}"

    # Skip if exists (unless --redeploy called force_delete first)
    if sudo virsh dominfo "$name" &>/dev/null; then
        local state
        state=$(sudo virsh domstate "$name" 2>/dev/null || echo "unknown")
        [[ "$state" == "shut off" ]] && sudo virsh start "$name" 2>/dev/null || true
        ok "$name exists (state: $state) — skipping."
        return 0
    fi

    log "Deploying $name [type=$type, ${ram}MB, ${vcpu}vCPU]..."

    # Determine base image and disk
    local base_img disk_path os_var backing_fmt extra_args=""
    case "$type" in
        sonic)
            if [[ "$SONIC_DISK_FORMAT" == "qcow2" ]]; then
                base_img="$IMG_DIR/sonic-vs.qcow2"; backing_fmt="qcow2"
            else
                base_img="$IMG_DIR/sonic-vs.img"; backing_fmt="raw"
            fi
            os_var="ubuntu20.04"
            # SONiC does NOT support cloud-init; uses ZTP for DHCP on eth0
            # Default credentials: admin / amolla01
            ;;
        ubuntu)
            base_img="$IMG_DIR/ubuntu-cloud.qcow2"; backing_fmt="qcow2"
            os_var="ubuntu24.04"
            create_cloud_init_iso "$name" "$user" "$pass"
            extra_args="--disk path=${CLOUD_INIT_DIR}/${name}-cidata.iso,device=cdrom"
            ;;
        chr)
            base_img="$IMG_DIR/chr.qcow2"; backing_fmt="qcow2"
            os_var="generic"
            # CHR does not support cloud-init
            ;;
    esac

    [[ ! -f "$base_img" ]] && { err "Base image missing: $base_img"; return 1; }

    # Determine root disk size based on role
    local root_disk_gb
    case "$type" in
        sonic) root_disk_gb=$SONIC_ROOT_DISK_GB ;;
        chr)   root_disk_gb=$CHR_ROOT_DISK_GB ;;
        ubuntu)
            case "$name" in
                Host12_1|Host34_1|HostB12_1) root_disk_gb=$SERVER_CONTROLLER_ROOT_DISK_GB ;;
                Host12_2|Host12_3|Host34_2)  root_disk_gb=$SERVER_WORKER_ROOT_DISK_GB ;;
                HostB12_2|MonitorSrv)        root_disk_gb=$SERVER_GATEWAY_ROOT_DISK_GB ;;
                Exit_Router*)                root_disk_gb=$UBUNTU_EXIT_ROUTER_ROOT_DISK_GB ;;
                *)                           root_disk_gb=$SERVER_ROOT_DISK_GB ;;
            esac
            ;;
        *) root_disk_gb=20 ;;
    esac

    # Create COW disk (thin provisioned, shares base)
    disk_path="$DISK_DIR/${name}.qcow2"
    sudo qemu-img create -f qcow2 -b "$base_img" -F "$backing_fmt" "$disk_path" "${root_disk_gb}G" >/dev/null

    # Create Ceph OSD disks for eligible servers (empty raw qcow2, no backing)
    local osd_disk_args=""
    if [[ "$type" == "ubuntu" ]]; then
        case "$name" in
            Host12_1|Host12_2|Host12_3|Host34_1|Host34_2|HostB12_1)
                for ((d=1; d<=CEPH_OSD_DISKS_PER_NODE; d++)); do
                    local osd_disk="$DISK_DIR/${name}-osd${d}.qcow2"
                    sudo qemu-img create -f qcow2 "$osd_disk" "${CEPH_OSD_DISK_GB}G" >/dev/null
                    osd_disk_args+=" --disk path=${osd_disk},format=qcow2,bus=virtio"
                done
                log "  + ${CEPH_OSD_DISKS_PER_NODE}× Ceph OSD disks (${CEPH_OSD_DISK_GB}GB each)"
                ;;
        esac
    fi

    # Build NIC arguments: NIC0 = mgmt, NIC1+ = fabric
    # Keep the management NIC on virtio so it remains the first enumerated NIC.
    # CHR fabric NICs use virtio with host-side offload disabled in libvirt XML.
    # Root cause: QEMU virtio (default) passes partial TCP checksums through OVS
    # bridges. Neither rtl8139 nor e1000 fixed this. The real fix is virtio with
    # <host csum='off' gso='off' tso4='off' tso6='off'/> in the domain XML —
    # this disables VIRTIO_NET_F_CSUM advertisement, forcing RouterOS to compute
    # full TCP checksums in software before handing frames to the vNIC.
    # Post-creation XML patching is applied after virt-install (see below).
    local mgmt_mac mgmt_model="virtio" fabric_model="virtio"
    # Note: e1000 was previously used for SONiC but causes eth ordering issues
    mgmt_mac=$(gen_mac "$name" "mgmt")
    local nic_args="--network network=${MGMT_NET_NAME},model=${mgmt_model},mac=${mgmt_mac}"

    if [[ -n "$bridges" ]]; then
        IFS=',' read -ra BR_LIST <<< "$bridges"
        local idx=0
        for br in "${BR_LIST[@]}"; do
            if [[ "$br" =~ ^@([0-9]+)$ ]]; then
                # @N = insert N real virtio NICs connected to the isolated br-pad
                # OVS bridge (no external peers).  Each NIC has a unique MAC and
                # consumes one NIC-index slot so that subsequent bridges land on
                # the correct port_config.ini index inside the SONiC KVM VS.
                # Example: @49 advances idx from 3 → 52 so that br-L1-S2/br-L1-S1
                # land on NIC53/NIC54 = Ethernet64/Ethernet68 (QSFP+5/6).
                # NOTE: --network none is virt-install's global "disable networking"
                # flag — it does NOT create a NIC — hence we use br-pad instead.
                local pad_count="${BASH_REMATCH[1]}"
                for ((pad=0; pad<pad_count; pad++)); do
                    local pad_mac
                    pad_mac=$(gen_mac "$name" "pad${idx}")
                    nic_args+=" --network network=br-pad,model=virtio,mac=${pad_mac}"
                    idx=$((idx + 1))
                done
            elif [[ "$br" == "none" ]]; then
                nic_args+=" --network none"
                idx=$((idx + 1))
            else
                local fab_mac
                fab_mac=$(gen_mac "$name" "fab${idx}")
                nic_args+=" --network network=${br},model=${fabric_model},mac=${fab_mac}"
                idx=$((idx + 1))
            fi
        done
    fi

    # Deploy
    local virt_install_log="$TMP_DIR/${name}-virt-install.log"
    if sudo virt-install \
        --name "$name" \
        --ram "$ram" \
        --vcpus "$vcpu" \
        --disk path="$disk_path",format=qcow2,bus=virtio \
        $extra_args \
        $osd_disk_args \
        --os-variant "$os_var" \
        $nic_args \
        --graphics none \
        --console pty,target_type=serial \
        --serial pty \
        --virt-type kvm \
        --import \
        --noautoconsole >"$virt_install_log" 2>&1; then
        ok "$name deployed. Console: sudo virsh console $name"
        rm -f "$virt_install_log"
    else
        err "$name deployment FAILED. virt-install output:"
        cat "$virt_install_log" | tee -a "$LOG_FILE"
        rm -f "$virt_install_log"
        sudo rm -f "$disk_path" "$CLOUD_INIT_DIR/${name}-cidata.iso"
        return 1
    fi

    # --- CHR: Patch libvirt XML to disable virtio checksum offload on fabric NICs ---
    # Without this, RouterOS sends TCP with partial checksums that OVS forwards
    # unchanged to the Border_Leaf tap → SONiC's TCP stack drops all SYNs → BGP
    # sessions between Exit_Router and Border_Leaf never form.
    # The fix disables VIRTIO_NET_F_CSUM advertisement in QEMU, forcing the guest
    # to compute full TCP checksums in software.
#     if [[ "$type" == "chr" && -n "$bridges" ]]; then
#         log "  Patching $name XML: disabling virtio checksum offload on fabric NICs..."
#         sudo virsh destroy "$name" 2>/dev/null || true
#         sleep 1

#         # Dump current XML, inject <driver><host csum='off'.../></driver> into
#         # each virtio interface that is NOT on the management network.
#         local xml_file="$TMP_DIR/${name}-patched.xml"
#         sudo virsh dumpxml --inactive "$name" > "$xml_file"

#         # Use python3 to safely modify the XML (avoids fragile sed on multiline XML)
#         python3 - "$xml_file" "$MGMT_NET_NAME" <<'PYEOF'
# import sys, xml.etree.ElementTree as ET

# xml_file = sys.argv[1]
# mgmt_net = sys.argv[2]

# tree = ET.parse(xml_file)
# root = tree.getroot()
# modified = False

# for iface in root.iter('interface'):
#     if iface.get('type') != 'network':
#         continue
#     source = iface.find('source')
#     if source is None:
#         continue
#     # Skip management NIC
#     if source.get('network') == mgmt_net:
#         continue
#     model = iface.find('model')
#     if model is None or model.get('type') != 'virtio':
#         continue
#     # Remove existing <driver> if present
#     driver = iface.find('driver')
#     if driver is not None:
#         iface.remove(driver)
#     # Insert <driver name='vhost'><host csum='off' gso='off' tso4='off' tso6='off'/></driver>
#     driver = ET.SubElement(iface, 'driver', name='vhost')
#     ET.SubElement(driver, 'host', csum='off', gso='off', tso4='off', tso6='off')
#     modified = True

# if modified:
#     tree.write(xml_file, xml_declaration=True, encoding='unicode')
#     print(f"Patched: virtio offload disabled on fabric NICs")
# else:
#     print("No virtio fabric NICs found to patch")
# PYEOF

#         sudo virsh define "$xml_file" >/dev/null 2>&1
#         sudo virsh start "$name" >/dev/null 2>&1
#         rm -f "$xml_file"
#         ok "  $name: virtio offload disabled — RouterOS will compute full TCP checksums."
