}

phase4_deploy() {
    header "PHASE 4: Deploy VMs"

    local vm_list=("${TARGET_VMS[@]}")
    local total=${#vm_list[@]} count=0 success=0 failed=0
    local total_ram=0
    for vm in "${vm_list[@]}"; do
        total_ram=$((total_ram + VM_RAM[$vm]))
    done
    log "Deploying $total VMs (total RAM: ${total_ram} MB)..."

    for vm in "${vm_list[@]}"; do
        if deploy_single_vm "$vm"; then
            # Enable autostart so VMs boot automatically if hypervisor restarts
            sudo virsh autostart "$vm" 2>/dev/null || true
            success=$((success + 1))
        else
            failed=$((failed + 1))
        fi
        count=$((count + 1))
        printf "  ├─ Progress: %d/%d\n" "$count" "$total"
    done

    echo ""
    log "Deploy: $success OK, $failed FAILED out of $total. (autostart enabled)"
    [[ $failed -gt 0 ]] && warn "Some VMs failed. Check errors above."
}

# ======================= PHASE 5: VALIDATION ================================
phase5_validate() {
    header "PHASE 5: SSH Connectivity Validation"

    local vm_list=("${TARGET_VMS[@]}")
    local boot_wait=180

    # If validating specific VMs (not full deploy), skip the long boot wait
    if [[ ${#vm_list[@]} -lt ${#VM_DEPLOY_ORDER[@]} ]]; then
        boot_wait=30
        log "Targeted validation (${#vm_list[@]} VMs) — waiting ${boot_wait}s..."
    else
        log "Waiting ${boot_wait}s for VMs to boot (SONiC needs ~2-3 min for ZTP/DHCP)..."
    fi
    sleep $boot_wait

    local pass=0 fail_count=0

    for vm in "${vm_list[@]}"; do
        local ip="${VM_MGMT_IP[$vm]}"
        local type="${VM_TYPE[$vm]}"
        local user="${VM_USER[$type]}"
        local pass_str="${VM_PASS[$type]}"
        local attempt=1 reachable=false

        printf "  %-18s (%s) " "$vm" "$ip"

        while [[ $attempt -le $SSH_MAX_RETRIES ]]; do
            if ping -c 1 -W 2 "$ip" &>/dev/null; then
                local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=$SSH_TIMEOUT"
                local ssh_result=""
                if [[ -n "$pass_str" ]]; then
                    ssh_result=$(sshpass -p "$pass_str" ssh $ssh_opts "$user@$ip" "echo ok" 2>/dev/null || true)
                else
                    ssh_result=$(ssh $ssh_opts "$user@$ip" "echo ok" 2>/dev/null || true)
                fi
                if [[ "$ssh_result" == "ok" ]]; then
                    reachable=true
                    break
                fi
            fi
            printf "."
            attempt=$((attempt + 1))
            sleep $SSH_RETRY_DELAY
        done

        if $reachable; then
            echo -e " ${GRN}✓ SSH OK${RST}"
            pass=$((pass + 1))
        else
            if ping -c 1 -W 2 "$ip" &>/dev/null; then
                echo -e " ${YLW}△ PING OK (SSH not ready)${RST}"
                pass=$((pass + 1))
            else
                echo -e " ${RED}✗ UNREACHABLE${RST}"
                fail_count=$((fail_count + 1))
            fi
        fi
    done

    echo ""
    log "Validation: $pass reachable, $fail_count unreachable / ${#vm_list[@]} total."
}

# ======================= PHASE 5.5: SERVER POST-BOOT CONFIG =================
# Configures Ubuntu servers with:
#   - Virtio TX checksum offload fix (hypervisor-side)
#   - NAT masquerade for internet access (apt packages)
#   - FRR installation via proxy
#   - Netplan fabric interface configuration (BGP unnumbered)
#   - FRR BGP configuration with loopback announcement
#   - Loopback interface (lo) with routable IP
#
# This phase was added after discovering that deploy_lab_v13.sh originally
# deployed servers with management-only connectivity but no fabric config.
# The redeploy_hostb12.sh script was needed to fix this — now integrated.
# ==========================================================================

configure_server_virtio_fix() {
    # Disable TX checksum offload on tap interfaces connected to fabric bridges.
    # Without this fix, TCP (including BGP port 179) fails between VMs connected
    # through Linux/OVS bridges because virtio offloads checksum computation to
    # a physical NIC that doesn't exist in a virtual bridge path.
    local vm_name="$1"
    local bridges="${VM_BRIDGES[$vm_name]:-}"
    [[ -z "$bridges" ]] && return 0

    IFS=',' read -ra BR_LIST <<< "$bridges"
    local idx=0
    for br in "${BR_LIST[@]}"; do
        [[ "$br" =~ ^@[0-9]+$ || "$br" == "none" || "$br" == "br-pad" ]] && continue
        # Find tap interface attached to this bridge for this VM
        local tap
        tap=$(sudo ovs-vsctl list-ports "$br" 2>/dev/null | grep "^vnet" | while read -r port; do
            # Check if this tap belongs to our VM by examining the qemu process
            local vm_of_port
            vm_of_port=$(sudo virsh domiflist "$vm_name" 2>/dev/null | grep "$port" | head -1)
            [[ -n "$vm_of_port" ]] && echo "$port" && break
        done)
        if [[ -n "$tap" ]]; then
            sudo ethtool -K "$tap" tx off 2>/dev/null || true
        fi
        idx=$((idx + 1))
    done
}

configure_server_networking() {
    local vm_name="$1"
    local ip="${VM_MGMT_IP[$vm_name]}"
    local user="${VM_USER[ubuntu]}"
    local pass="${VM_PASS[ubuntu]}"
    local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=10"
    local loopback_ip="${SERVER_LOOPBACK_IP[$vm_name]:-}"
    local router_id="${SERVER_ROUTER_ID[$vm_name]:-}"
    local bgp_asn="${SERVER_BGP_ASN[$vm_name]:-65200}"
    local peer1_asn="${SERVER_PEER1_ASN[$vm_name]:-}"
    local peer2_asn="${SERVER_PEER2_ASN[$vm_name]:-}"
    local peer1_desc="${SERVER_PEER1_DESC[$vm_name]:-Peer1}"
    local peer2_desc="${SERVER_PEER2_DESC[$vm_name]:-Peer2}"

    [[ -z "$loopback_ip" ]] && { warn "$vm_name: No loopback IP defined, skipping FRR config"; return 0; }

    # Test SSH first
    local ssh_ok
    ssh_ok=$(sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "echo ok" 2>/dev/null || true)
    [[ "$ssh_ok" != "ok" ]] && { warn "$vm_name: SSH not ready at $ip, skipping server config"; return 1; }

    log "  Configuring $vm_name ($ip) — loopback=$loopback_ip, ASN=$bgp_asn..."

    # ---- CRITICAL: Disable cloud-init network management ----
    # Without this, cloud-init overwrites /etc/netplan/ on every reboot,
    # destroying Day0/Day1 configs (10-loopback.yaml, 20-fabric.yaml, FRR, etc.)
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        sudo mkdir -p /etc/cloud/cloud.cfg.d
        echo 'network: {config: disabled}' | sudo tee /etc/cloud/cloud.cfg.d/99-disable-network-config.cfg > /dev/null
        sudo touch /etc/cloud/cloud-init.disabled
    " 2>/dev/null || true

    # Ubuntu Noble cloud images use predictable interface names:
    #   enp1s0 = NIC0 (mgmt), enp2s0 = NIC1 (fabric0), enp3s0 = NIC2 (fabric1)
    # Discover actual fabric interface names from the VM
    local fab0_name fab1_name
    fab0_name=$(sshpass -p "$pass" ssh $ssh_opts "$user@$ip" \
        "ip -o link show | grep -v lo | grep -v enp1s0 | awk -F': ' 'NR==1{print \$2}'" 2>/dev/null || echo "enp2s0")
    fab1_name=$(sshpass -p "$pass" ssh $ssh_opts "$user@$ip" \
        "ip -o link show | grep -v lo | grep -v enp1s0 | awk -F': ' 'NR==2{print \$2}'" 2>/dev/null || echo "enp3s0")

    # Configure proxy for apt (corporate network)
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "sudo bash -c '
        mkdir -p /etc/apt/apt.conf.d
        echo \"Acquire::http::Proxy \\\"$HTTP_PROXY\\\";\" > /etc/apt/apt.conf.d/90proxy
        echo \"Acquire::https::Proxy \\\"$HTTPS_PROXY\\\";\" >> /etc/apt/apt.conf.d/90proxy
    '" 2>/dev/null || true

    # Install FRR
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        if ! command -v vtysh &>/dev/null; then
            sudo apt-get update -qq 2>/dev/null
            sudo apt-get install -y -qq frr frr-pythontools 2>/dev/null
        fi
    " 2>/dev/null || { warn "$vm_name: FRR install failed (check proxy/internet)"; }

    # Configure loopback IP
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        sudo ip addr add ${loopback_ip} dev lo 2>/dev/null || true
        # Make persistent via netplan drop-in
        sudo mkdir -p /etc/netplan
        sudo tee /etc/netplan/10-loopback.yaml > /dev/null <<LOEOF
network:
  version: 2
  ethernets:
    lo:
      addresses:
        - ${loopback_ip}
LOEOF
    " 2>/dev/null || true

    # Configure fabric interfaces (unnumbered — IPv6 link-local for BGP)
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        sudo ip link set ${fab0_name} up 2>/dev/null || true
        sudo ip link set ${fab1_name} up 2>/dev/null || true
        # Add synthetic nexthop for BGP unnumbered compatibility with SONiC
        sudo ip addr add 169.254.0.1/32 dev ${fab0_name} 2>/dev/null || true
        sudo ip addr add 169.254.0.1/32 dev ${fab1_name} 2>/dev/null || true
        # Netplan for fabric interfaces
        sudo tee /etc/netplan/20-fabric.yaml > /dev/null <<FABEOF
network:
  version: 2
  ethernets:
    ${fab0_name}:
      dhcp4: false
      link-local: [ipv6]
      mtu: 9000
    ${fab1_name}:
      dhcp4: false
      link-local: [ipv6]
      mtu: 9000
FABEOF
        sudo netplan apply 2>/dev/null || true
    " 2>/dev/null || true

    # Configure FRR daemons file
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        sudo sed -i 's/^bgpd=no/bgpd=yes/' /etc/frr/daemons 2>/dev/null || true
        sudo sed -i 's/^zebra=no/zebra=yes/' /etc/frr/daemons 2>/dev/null || true
    " 2>/dev/null || true

    # Deploy FRR configuration
    local frr_conf="frr version 8.4
frr defaults traditional
hostname ${vm_name}
log syslog informational
no ipv6 forwarding
!
router bgp ${bgp_asn}
 bgp router-id ${router_id}
 bgp bestpath as-path multipath-relax
 no bgp ebgp-requires-policy
 neighbor ${fab0_name} interface remote-as ${peer1_asn}
 neighbor ${fab0_name} description ${peer1_desc}
 neighbor ${fab1_name} interface remote-as ${peer2_asn}
 neighbor ${fab1_name} description ${peer2_desc}
 !
 address-family ipv4 unicast
  redistribute connected
  neighbor ${fab0_name} activate
  neighbor ${fab0_name} soft-reconfiguration inbound
  neighbor ${fab1_name} activate
  neighbor ${fab1_name} soft-reconfiguration inbound
 exit-address-family
!
line vty
!"
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        echo '${frr_conf}' | sudo tee /etc/frr/frr.conf > /dev/null
        sudo chown frr:frr /etc/frr/frr.conf
        sudo chmod 640 /etc/frr/frr.conf
        sudo systemctl restart frr
    " 2>/dev/null || { warn "$vm_name: FRR config deploy failed"; return 1; }

    ok "  $vm_name: FRR + loopback configured (${loopback_ip}, AS ${bgp_asn})"
}

phase5_5_server_config() {
    header "PHASE 5.5: Server Post-Boot Configuration (FRR + Loopback + Virtio Fix)"

    # Only configure Ubuntu servers that are in our target list
    local server_list=()
    for vm in "${TARGET_VMS[@]}"; do
        [[ "${VM_TYPE[$vm]}" == "ubuntu" ]] && server_list+=("$vm")
    done

    if [[ ${#server_list[@]} -eq 0 ]]; then
        log "No Ubuntu servers in target list — skipping server config phase."
        return 0
    fi

#     # Enable NAT masquerade on hypervisor for server internet access (apt)
#     log "Enabling NAT masquerade for management subnet..."
#     if ! sudo iptables -t nat -C POSTROUTING -s 172.16.2.0/24 ! -d 172.16.2.0/24 -j MASQUERADE 2>/dev/null; then
#         sudo iptables -t nat -A POSTROUTING -s 172.16.2.0/24 ! -d 172.16.2.0/24 -j MASQUERADE
#         ok "NAT masquerade enabled for 172.16.2.0/24"
#     else
#         ok "NAT masquerade already active."
#     fi
#     # Persist NAT rule so it survives hypervisor reboot
#     local nat_persist="/etc/networkd-dispatcher/routable.d/50-dc-lab-nat.sh"
#     if [[ ! -f "$nat_persist" ]]; then
#         sudo mkdir -p "$(dirname "$nat_persist")"
#         sudo tee "$nat_persist" > /dev/null <<'NATRULE'
# #!/bin/bash
# # Persistent NAT masquerade for dc-lab management subnet (auto-generated by deploy_lab_v13.sh)
# iptables -t nat -C POSTROUTING -s 172.16.2.0/24 ! -d 172.16.2.0/24 -j MASQUERADE 2>/dev/null || \
# iptables -t nat -A POSTROUTING -s 172.16.2.0/24 ! -d 172.16.2.0/24 -j MASQUERADE
 # Enable NAT masquerade on hypervisor for server internet access (apt)
 log "Enabling NAT masquerade for management subnet..."
 if ! sudo iptables -t nat -C POSTROUTING -s 10.10.1.0/24 ! -d 10.10.1.0/24 -j MASQUERADE 2>/dev/null; then
   sudo iptables -t nat -A POSTROUTING -s 10.10.1.0/24 ! -d 10.10.1.0/24 -j MASQUERADE
   ok "NAT masquerade enabled for 10.10.1.0/24"
 else
   ok "NAT masquerade already active."
 fi
 # Persist NAT rule so it survives hypervisor reboot
 local nat_persist="/etc/networkd-dispatcher/routable.d/50-dc-lab-nat.sh"
 if [[ ! -f "$nat_persist" ]]; then
 sudo mkdir -p "$(dirname "$nat_persist")"
 sudo tee "$nat_persist" > /dev/null <<'NATRULE'
#!/bin/bash
# Persistent NAT masquerade for dc-lab management subnet (auto-generated by deploy_lab_v13.sh)
iptables -t nat -C POSTROUTING -s 10.10.1.0/24 ! -d 10.10.1.0/24 -j MASQUERADE 2>/dev/null || \
iptables -t nat -A POSTROUTING -s 10.10.1.0/24 ! -d 10.10.1.0/24 -j MASQUERADE

NATRULE
        sudo chmod +x "$nat_persist"
        ok "NAT masquerade rule persisted to $nat_persist"
    fi

    # Apply virtio TX checksum fix for all target fabric VMs.
    # The symptom is asymmetric: switch-to-server TCP can fail even when only
    # the switch-side tap keeps TX checksum offload enabled.
    log "Applying virtio TX checksum offload fix on fabric tap interfaces for all target VMs..."
    for vm in "${TARGET_VMS[@]}"; do
        [[ -n "${VM_BRIDGES[$vm]:-}" ]] && configure_server_virtio_fix "$vm"
    done

    # Persist the virtio TX offload fix via a libvirt qemu hook so it re-applies
    # after any VM start (including hypervisor reboot → autostart).
    local qemu_hook="/etc/libvirt/hooks/qemu"
    if [[ ! -f "$qemu_hook" ]] || ! grep -q "dc-lab-tx-offload" "$qemu_hook" 2>/dev/null; then
        log "Installing libvirt qemu hook for persistent TX offload fix..."
        sudo mkdir -p /etc/libvirt/hooks
        sudo tee "$qemu_hook" > /dev/null <<'QEMUHOOK'
#!/bin/bash
# dc-lab-tx-offload: Disable TX checksum offload on all tap interfaces after VM start.
# Without this, TCP (including BGP) fails over virtio+OVS bridges.
# Triggered by libvirt on every VM start/migrate/restore.
GUEST="$1"
ACTION="$2"
if [[ "$ACTION" == "started" ]]; then
    sleep 2  # Wait for tap interfaces to be fully attached
    for tap in $(virsh domiflist "$GUEST" 2>/dev/null | awk '/vnet|tap/{print $1}'); do
        ethtool -K "$tap" tx off 2>/dev/null || true
    done
fi
QEMUHOOK
        sudo chmod +x "$qemu_hook"
        sudo systemctl restart libvirtd 2>/dev/null || true
        ok "Libvirt qemu hook installed — TX offload fix persists across reboots."
    fi

    # Wait for servers to stabilize after boot
    log "Waiting 15s for server cloud-init to complete..."
    sleep 15

    # Configure each server with FRR + loopback
    local configured=0 failed=0
    for vm in "${server_list[@]}"; do
        if configure_server_networking "$vm"; then
            configured=$((configured + 1))
        else
            failed=$((failed + 1))
        fi
    done

    echo ""
    log "Server config: $configured OK, $failed FAILED out of ${#server_list[@]}."
    [[ $failed -gt 0 ]] && warn "Some servers failed configuration. Run: $0 validate servers"
}

# ======================= PHASE 5.6: KUBERNETES NODE PREPARATION =============
# Prepares Ubuntu servers for Kubernetes (Kubespray) installation.
# Profile-aware: only applies steps relevant to the deployment profile.
#
#   win11_kvm:       Full prep — Squid proxy (hypervisor), DNS, K8s packages,
#                    swap disable, kernel modules, sysctl. Proxy goes through
#                    the hypervisor's Squid (172.16.2.1:3128) which chains to
#                    corporate cso.proxy.att.com:8080.
#
#   ubuntu_r620_kvm: Full prep — Same as win11_kvm but uses direct corporate
#                    proxy (cso.proxy.att.com:8080). More RAM available so
#                    K8s resource limits can be higher.
#
#   real_hardware:   Minimal prep — Only kernel modules + sysctl + swap.
#                    Network, DNS, and proxy are pre-configured by infra team.
#                    Packages assumed installed from golden image or Satellite.
#
# Servers with K8S_ENABLED flag get prepared. By default only HostB12_1 is
# enabled, but any server can be flagged for K8s.
# ==========================================================================

# --- K8s-enabled servers (extend this map to add more K8s nodes) ---
declare -A K8S_ENABLED
K8S_ENABLED[HostB12_1]=true
# K8S_ENABLED[HostB12_2]=true    # Uncomment to add second K8s node
# K8S_ENABLED[Host34_1]=true     # Uncomment for worker in Pod 3-4

configure_server_k8s_proxy() {
    # Configure apt and environment proxy for K8s package downloads.
    # Only needed for KVM lab profiles where the hypervisor provides proxy.
    local vm_name="$1"
    local ip="${VM_MGMT_IP[$vm_name]}"
    local user="${VM_USER[ubuntu]}"
    local pass="${VM_PASS[ubuntu]}"
    local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=10"
    local proxy_url=""
    local no_proxy_addrs=""

    case "$AUTOMATION_PROFILE" in
        win11_kvm)
            # WSL2 lab: hypervisor runs Squid on 172.16.2.1:3128
            proxy_url="http://172.16.2.1:3128"
            no_proxy_addrs="localhost,127.0.0.1,172.16.2.0/24,192.168.255.0/25,10.233.0.0/18,10.233.64.0/18"
            ;;
        ubuntu_r620_kvm)
            # Dell R620: direct corporate proxy access
            proxy_url="http://cso.proxy.att.com:8080"
            no_proxy_addrs="localhost,127.0.0.1,172.16.2.0/24,10.233.0.0/18,10.233.64.0/18"
            ;;
        real_hardware)
            # Physical infra: proxy handled externally
            return 0
            ;;
    esac

    log "    [$vm_name] Configuring apt + environment proxy (${proxy_url})..."
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "sudo bash -c '
        # Apt proxy
        mkdir -p /etc/apt/apt.conf.d
        cat > /etc/apt/apt.conf.d/90proxy <<PROXYEOF
Acquire::http::Proxy \"${proxy_url}\";
Acquire::https::Proxy \"${proxy_url}\";
PROXYEOF
        # Environment proxy (for pip, curl, wget, containerd pulls)
        grep -q \"http_proxy\" /etc/environment 2>/dev/null || cat >> /etc/environment <<ENVEOF
http_proxy=${proxy_url}
https_proxy=${proxy_url}
no_proxy=${no_proxy_addrs}
ENVEOF
    '" 2>/dev/null || { warn "$vm_name: proxy config failed"; return 1; }
}

configure_server_k8s_dns() {
    # Set DNS resolvers. Only needed for KVM lab profiles where VMs
    # have no upstream DNS configured by cloud-init beyond the hypervisor.
    local vm_name="$1"
    local ip="${VM_MGMT_IP[$vm_name]}"
    local user="${VM_USER[ubuntu]}"
    local pass="${VM_PASS[ubuntu]}"
    local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=10"

    case "$AUTOMATION_PROFILE" in
        real_hardware)
            # Physical infra: DNS pre-configured
            return 0
            ;;
    esac

    log "    [$vm_name] Setting DNS resolvers (8.8.8.8, 8.8.4.4)..."
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" \
        "sudo resolvectl dns enp1s0 8.8.8.8 8.8.4.4 2>/dev/null || true" 2>/dev/null
}

configure_server_k8s_packages() {
    # Install Kubernetes prerequisite packages.
    # Skipped for real_hardware (assumed pre-installed from golden image).
    local vm_name="$1"
    local ip="${VM_MGMT_IP[$vm_name]}"
    local user="${VM_USER[ubuntu]}"
    local pass="${VM_PASS[ubuntu]}"
    local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=10"

    case "$AUTOMATION_PROFILE" in
        real_hardware)
            log "    [$vm_name] Skipping package install (real_hardware profile)."
            return 0
            ;;
    esac

    log "    [$vm_name] Installing Kubernetes prerequisites..."
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        sudo apt-get update -qq 2>/dev/null
        sudo apt-get install -y -qq \
            apt-transport-https ca-certificates curl gnupg lsb-release \
            conntrack socat ipset ipvsadm software-properties-common 2>/dev/null
    " 2>/dev/null || { warn "$vm_name: K8s package install had errors (check proxy)"; return 1; }
}

configure_server_k8s_swap() {
    # Disable swap (required by kubelet on all profiles).
    local vm_name="$1"
    local ip="${VM_MGMT_IP[$vm_name]}"
    local user="${VM_USER[ubuntu]}"
    local pass="${VM_PASS[ubuntu]}"
    local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=10"

    log "    [$vm_name] Disabling swap..."
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        sudo swapoff -a
        sudo sed -i '/\sswap\s/d' /etc/fstab
    " 2>/dev/null || true
}

configure_server_k8s_kernel() {
    # Load kernel modules and set sysctl parameters for Kubernetes networking.
    # Required on ALL profiles (KVM and real hardware).
    local vm_name="$1"
    local ip="${VM_MGMT_IP[$vm_name]}"
    local user="${VM_USER[ubuntu]}"
    local pass="${VM_PASS[ubuntu]}"
    local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=10"

    log "    [$vm_name] Loading kernel modules + sysctl for K8s..."
    sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "sudo bash -c '
        # Load modules now
        modprobe br_netfilter overlay ip_vs ip_vs_rr ip_vs_wrr ip_vs_sh 2>/dev/null

        # Persist modules across reboots
        cat > /etc/modules-load.d/k8s.conf <<MODEOF
br_netfilter
overlay
ip_vs
ip_vs_rr
ip_vs_wrr
ip_vs_sh
MODEOF

        # Sysctl for K8s networking
        cat > /etc/sysctl.d/99-kubernetes.conf <<SYSEOF
net.bridge.bridge-nf-call-iptables = 1
net.bridge.bridge-nf-call-ip6tables = 1
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
SYSEOF
        sysctl --system > /dev/null 2>&1
    '" 2>/dev/null || { warn "$vm_name: kernel module setup failed"; return 1; }
}

configure_server_k8s_node() {
    # Orchestrate all K8s preparation steps for a single server.
    # Steps are profile-aware — each function checks the profile internally.
    local vm_name="$1"
    local ip="${VM_MGMT_IP[$vm_name]}"
    local user="${VM_USER[ubuntu]}"
    local pass="${VM_PASS[ubuntu]}"
    local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=10"

    # Test SSH first
    local ssh_ok
    ssh_ok=$(sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "echo ok" 2>/dev/null || true)
    if [[ "$ssh_ok" != "ok" ]]; then
        warn "$vm_name: SSH not ready at $ip, skipping K8s prep"
        return 1
    fi

    log "  Preparing $vm_name ($ip) for Kubernetes [profile=$AUTOMATION_PROFILE]..."

    configure_server_k8s_proxy "$vm_name"   || true
    configure_server_k8s_dns "$vm_name"     || true
    configure_server_k8s_packages "$vm_name" || true
    configure_server_k8s_swap "$vm_name"
    configure_server_k8s_kernel "$vm_name"  || return 1

    # Verification
    local verify_result
    verify_result=$(sshpass -p "$pass" ssh $ssh_opts "$user@$ip" "
        echo -n 'br_netfilter:'; lsmod | grep -qw br_netfilter && echo OK || echo MISSING
        echo -n 'ip_forward:'; cat /proc/sys/net/ipv4/ip_forward
        echo -n 'swap:'; free -h | grep -i swap | awk '{print \$2}'
    " 2>/dev/null || echo "verify failed")

    if echo "$verify_result" | grep -q "br_netfilter:OK"; then
        ok "  $vm_name: K8s node preparation complete."
        return 0
    else
        warn "$vm_name: Verification issues — $verify_result"
        return 1
    fi
}

phase5_6_k8s_prep() {
    header "PHASE 5.6: Kubernetes Node Preparation"

    # Filter target VMs to only K8s-enabled Ubuntu servers
    local k8s_servers=()
    for vm in "${TARGET_VMS[@]}"; do
        if [[ "${VM_TYPE[$vm]}" == "ubuntu" && "${K8S_ENABLED[$vm]:-false}" == "true" ]]; then
            k8s_servers+=("$vm")
        fi
    done

    if [[ ${#k8s_servers[@]} -eq 0 ]]; then
        log "No K8s-enabled servers in target list — skipping."
        log "  (To enable: set K8S_ENABLED[<server>]=true in script config)"
        return 0
    fi

    log "K8s-enabled servers: ${k8s_servers[*]}"
    log "Profile: $AUTOMATION_PROFILE"
    case "$AUTOMATION_PROFILE" in
        win11_kvm)      log "  Steps: proxy(squid) → DNS → packages → swap → kernel" ;;
        ubuntu_r620_kvm) log "  Steps: proxy(corporate) → DNS → packages → swap → kernel" ;;
        real_hardware)  log "  Steps: swap → kernel (proxy/DNS/packages skip)" ;;
    esac
    echo ""

    local configured=0 failed=0
    for vm in "${k8s_servers[@]}"; do
        if configure_server_k8s_node "$vm"; then
            configured=$((configured + 1))
        else
            failed=$((failed + 1))
        fi
    done

    echo ""
    log "K8s prep: $configured OK, $failed FAILED out of ${#k8s_servers[@]}."
    if [[ $configured -gt 0 ]]; then
        log "Next step: Run Kubespray to install K8s on prepared nodes."
        log "  cd ~/kubespray && ansible-playbook -i inventory/dc-lab/hosts.yml cluster.yml"
    fi
    [[ $failed -gt 0 ]] && warn "Some servers failed K8s prep. Check SSH and proxy connectivity."
}

