# ======================= TEARDOWN ==========================================
teardown() {
    header "TEARDOWN: Destroy All Lab Resources (Full Clean)"
    echo -e "${RED}WARNING: This destroys ALL lab VMs, disks, networks, OVS bridges, and iptables rules!${RST}"
    echo -e "${RED}Only base images in $IMG_DIR are preserved.${RST}"
    read -p "Type 'DESTROY' to confirm: " confirm
    [[ "$confirm" != "DESTROY" ]] && { log "Aborted."; exit 0; }

    # ─── Step 1: Destroy and undefine ALL known VMs ───────────────────────────
    log "Step 1/6: Destroying all lab VMs..."
    for vm in "${VM_DEPLOY_ORDER[@]}"; do
        if sudo virsh dominfo "$vm" &>/dev/null; then
            sudo virsh destroy "$vm" 2>/dev/null || true
            sudo virsh undefine "$vm" --nvram 2>/dev/null || \
                sudo virsh undefine "$vm" 2>/dev/null || true
        fi
    done
    # Catch orphan VMs that may not be in VM_DEPLOY_ORDER (e.g. leftover from previous versions)
    local all_domains
    all_domains=$(sudo virsh list --all --name 2>/dev/null | grep -E '^(Spine_|Leaf_|Border_Leaf|Exit_Router|Host|MonitorSrv)' || true)
    for orphan in $all_domains; do
        if sudo virsh dominfo "$orphan" &>/dev/null; then
            log "  Removing orphan VM: $orphan"
            sudo virsh destroy "$orphan" 2>/dev/null || true
            sudo virsh undefine "$orphan" --nvram 2>/dev/null || \
                sudo virsh undefine "$orphan" 2>/dev/null || true
        fi
    done
    ok "All VMs destroyed and undefined."

    # ─── Step 2: Remove ALL OVS ports and bridges ─────────────────────────────
    log "Step 2/6: Removing all OVS bridges and ports..."
    # First remove all ports from each bridge (catches vnet*, patch, custom ports)
    for br in "${FABRIC_BRIDGES[@]}"; do
        if sudo ovs-vsctl br-exists "$br" 2>/dev/null; then
            local ports
            ports=$(sudo ovs-vsctl list-ports "$br" 2>/dev/null || true)
            for port in $ports; do
                sudo ovs-vsctl --if-exists del-port "$br" "$port" 2>/dev/null || true
            done
            sudo ovs-vsctl --if-exists del-br "$br" 2>/dev/null || true
        fi
    done
    # Catch any orphan OVS bridges matching lab naming patterns
    local all_ovs_br
    all_ovs_br=$(sudo ovs-vsctl list-br 2>/dev/null || true)
    for br in $all_ovs_br; do
        if [[ "$br" == br-S* || "$br" == br-L* || "$br" == br-BL* || \
              "$br" == br-HB* || "$br" == br-MS* || "$br" == br-wan* || \
              "$br" == br-ER* ]]; then
            log "  Removing orphan OVS bridge: $br"
            local ports
            ports=$(sudo ovs-vsctl list-ports "$br" 2>/dev/null || true)
            for port in $ports; do
                sudo ovs-vsctl --if-exists del-port "$br" "$port" 2>/dev/null || true
            done
            sudo ovs-vsctl --if-exists del-br "$br" 2>/dev/null || true
        fi
    done
    ok "All OVS bridges and ports removed."

    # ─── Step 3: Destroy and undefine ALL libvirt networks ────────────────────
    log "Step 3/6: Removing all libvirt network definitions..."
    for br in "${FABRIC_BRIDGES[@]}"; do
        sudo virsh net-destroy "$br" 2>/dev/null || true
        sudo virsh net-undefine "$br" 2>/dev/null || true
    done
    sudo virsh net-destroy "$MGMT_NET_NAME" 2>/dev/null || true
    sudo virsh net-undefine "$MGMT_NET_NAME" 2>/dev/null || true
    # Remove the br-mgmt device (could be OVS bridge, Linux bridge, or OVS port)
    sudo pkill -9 -f "[d]nsmasq.*br-mgmt" 2>/dev/null || true
    sudo ovs-vsctl --if-exists del-br br-mgmt 2>/dev/null || true
    sudo ovs-vsctl --if-exists del-port br-mgmt 2>/dev/null || true
    sudo ip link set br-mgmt down 2>/dev/null || true
    sudo ip link delete dev br-mgmt 2>/dev/null || true
    sudo brctl delbr br-mgmt 2>/dev/null || true
    # Catch orphan libvirt networks matching lab patterns
    local all_nets
    all_nets=$(sudo virsh net-list --all --name 2>/dev/null | grep -E '^(br-S|br-L|br-BL|br-HB|br-MS|br-wan|br-ER|dc-mgmt)' || true)
    for net in $all_nets; do
        log "  Removing orphan libvirt network: $net"
        sudo virsh net-destroy "$net" 2>/dev/null || true
        sudo virsh net-undefine "$net" 2>/dev/null || true
    done
    ok "All libvirt networks removed."

    # ─── Step 4: Clean WAN bridge iptables NAT rules ──────────────────────────
    log "Step 4/6: Removing WAN NAT iptables rules..."
    for wan_idx in 1 2; do
        sudo iptables -t nat -D POSTROUTING -s "192.168.${wan_idx}.0/24" \
            ! -d "192.168.${wan_idx}.0/24" -j MASQUERADE 2>/dev/null || true
    done
    ok "WAN NAT iptables rules removed."

    # ─── Step 5: Remove all disks, cloud-init ISOs, and temp files ────────────
    log "Step 5/6: Cleaning disk images, cloud-init ISOs, and temp files..."
    sudo rm -rf "$DISK_DIR"/* "$CLOUD_INIT_DIR"/* "$TMP_DIR"/*
    ok "All disks, ISOs, and temp files removed."

    # ─── Step 6: Remove stale libvirt XML fragments from /etc/libvirt ─────────
    log "Step 6/6: Purging stale libvirt XML definitions..."
    # virsh undefine should handle this, but race conditions can leave fragments
    for vm in "${VM_DEPLOY_ORDER[@]}"; do
        sudo rm -f "/etc/libvirt/qemu/${vm}.xml" 2>/dev/null || true
        sudo rm -f "/etc/libvirt/qemu/autostart/${vm}.xml" 2>/dev/null || true
    done
    # Purge network XML fragments
    for br in "${FABRIC_BRIDGES[@]}"; do
        sudo rm -f "/etc/libvirt/qemu/networks/${br}.xml" 2>/dev/null || true
        sudo rm -f "/etc/libvirt/qemu/networks/autostart/${br}.xml" 2>/dev/null || true
    done
    sudo rm -f "/etc/libvirt/qemu/networks/${MGMT_NET_NAME}.xml" 2>/dev/null || true
    sudo rm -f "/etc/libvirt/qemu/networks/autostart/${MGMT_NET_NAME}.xml" 2>/dev/null || true
    # Restart libvirtd to flush any cached state
    sudo systemctl restart libvirtd 2>/dev/null || true
    ok "Stale libvirt XML purged; libvirtd restarted."

    echo ""
    ok "═══ TEARDOWN COMPLETE ═══"
    ok "Everything destroyed. Base images in $IMG_DIR preserved for next deploy."
    ok "Run with 'deploy' to recreate the full lab from scratch."
}

# ======================= STATUS REPORT ======================================
status_report() {
    header "LAB STATUS REPORT"
    printf "  ${BLD}%-18s %-10s %-16s %-8s %-6s${RST}\n" "VM" "STATE" "IP" "TYPE" "RAM"
    printf "  %-18s %-10s %-16s %-8s %-6s\n" "──────────────────" "──────────" "────────────────" "────────" "──────"

    local running=0 total_alloc=0
    for vm in "${VM_DEPLOY_ORDER[@]}"; do
        local state
        state=$(sudo virsh domstate "$vm" 2>/dev/null | tr -d '\n' || true)
        [[ -z "$state" ]] && state="undefined"
        local sc="$RST"
        case "$state" in running) sc="$GRN"; running=$((running+1)); total_alloc=$((total_alloc+VM_RAM[$vm])) ;; "shut off") sc="$YLW" ;; *) sc="$RED" ;; esac
        printf "  %-18s ${sc}%-10s${RST} %-16s %-8s %-6s\n" "$vm" "$state" "${VM_MGMT_IP[$vm]}" "${VM_TYPE[$vm]}" "${VM_RAM[$vm]}"
    done

    echo ""
    log "Running: $running/${#VM_DEPLOY_ORDER[@]} | RAM allocated: ${total_alloc} MB"
    echo ""
    log "OVS bridges: $(sudo ovs-vsctl list-br 2>/dev/null | wc -l) active"
}

# ======================= PHASE T: PLATFORM TOOLS DOWNLOAD ===================
# Downloads and installs all platform software required for the full-stack
# deployment pipeline (Kubernetes, Helm, Ceph, OpenStack, MaaS, Ansible, etc.)
#
# This phase is proxy-aware and respects --no-proxy / --proxy-url flags.
# All binaries are installed to /usr/local/bin (system-wide).
# Helm repos and Kubespray are placed in $PROJECT_ROOT.
# ==========================================================================

# --- Platform Tool Versions (pinned for reproducibility) ---
KUBECTL_VERSION="${KUBECTL_VERSION:-v1.30.2}"
HELM_VERSION="${HELM_VERSION:-v3.15.2}"
KUBESPRAY_VERSION="${KUBESPRAY_VERSION:-v2.25.0}"
ARGOCD_VERSION="${ARGOCD_VERSION:-v2.11.3}"
ROOK_VERSION="${ROOK_VERSION:-v1.14.7}"
CEPH_CSI_VERSION="${CEPH_CSI_VERSION:-v3.11.0}"
YQ_VERSION="${YQ_VERSION:-v4.44.2}"
K9S_VERSION="${K9S_VERSION:-v0.32.5}"

# --- Download URLs ---
KUBECTL_URL="https://dl.k8s.io/release/${KUBECTL_VERSION}/bin/linux/amd64/kubectl"
KUBECTL_SHA_URL="https://dl.k8s.io/release/${KUBECTL_VERSION}/bin/linux/amd64/kubectl.sha256"
HELM_URL="https://get.helm.sh/helm-${HELM_VERSION}-linux-amd64.tar.gz"
KUBESPRAY_URL="https://github.com/kubernetes-sigs/kubespray/archive/refs/tags/${KUBESPRAY_VERSION}.tar.gz"
ARGOCD_URL="https://github.com/argoproj/argo-cd/releases/download/${ARGOCD_VERSION}/argocd-linux-amd64"
YQ_URL="https://github.com/mikefarah/yq/releases/download/${YQ_VERSION}/yq_linux_amd64"
K9S_URL="https://github.com/derailed/k9s/releases/download/${K9S_VERSION}/k9s_Linux_amd64.tar.gz"

# --- Helm Chart Repositories (added after Helm install) ---
declare -A HELM_REPOS
HELM_REPOS[bitnami]="https://charts.bitnami.com/bitnami"
HELM_REPOS[openstack-helm]="https://tarballs.opendev.org/openstack/openstack-helm"
HELM_REPOS[openstack-helm-infra]="https://tarballs.opendev.org/openstack/openstack-helm-infra"
HELM_REPOS[rook-release]="https://charts.rook.io/release"
HELM_REPOS[ingress-nginx]="https://kubernetes.github.io/ingress-nginx"
HELM_REPOS[jetstack]="https://charts.jetstack.io"
HELM_REPOS[prometheus-community]="https://prometheus-community.github.io/helm-charts"
HELM_REPOS[grafana]="https://grafana.github.io/helm-charts"
HELM_REPOS[argo]="https://argoproj.github.io/argo-helm"
HELM_REPOS[airship]="https://airship-treasuremap.github.io/treasuremap"

# --- APT packages needed for full-stack pipeline ---
FULLSTACK_APT_PKGS=(
    ansible python3-pip python3-venv python3-jinja2 python3-yaml
    python3-netaddr python3-cryptography
    git make gcc python3-dev libffi-dev libssl-dev
    nfs-common open-iscsi lvm2 thin-provisioning-tools
    ethtool ipvsadm conntrack socat
)

install_kubectl() {
    local version="$KUBECTL_VERSION"
    if command -v kubectl &>/dev/null; then
        local current
        current=$(kubectl version --client --short 2>/dev/null | awk '{print $3}' || echo "unknown")
        if [[ "$current" == "$version" ]]; then
            ok "kubectl $version already installed."
            return 0
        fi
    fi

    log "Installing kubectl $version..."
    download_safe "$KUBECTL_URL" "$TMP_DIR/kubectl" "kubectl $version"
    download_safe "$KUBECTL_SHA_URL" "$TMP_DIR/kubectl.sha256" "kubectl SHA256"

    # Verify SHA256
    local expected actual
    expected=$(cat "$TMP_DIR/kubectl.sha256")
    actual=$(sha256sum "$TMP_DIR/kubectl" | awk '{print $1}')
    if [[ "$actual" != "$expected" ]]; then
        die "kubectl SHA256 mismatch! Expected: $expected Got: $actual"
    fi
    sudo install -o root -g root -m 0755 "$TMP_DIR/kubectl" /usr/local/bin/kubectl
    rm -f "$TMP_DIR/kubectl" "$TMP_DIR/kubectl.sha256"
    ok "kubectl $version installed."
}

install_helm() {
    local version="$HELM_VERSION"
    if command -v helm &>/dev/null; then
        local current
        current=$(helm version --short 2>/dev/null | cut -d'+' -f1 || echo "unknown")
        if [[ "$current" == "$version" ]]; then
            ok "Helm $version already installed."
            return 0
        fi
    fi

    log "Installing Helm $version..."
    download_safe "$HELM_URL" "$TMP_DIR/helm.tar.gz" "Helm $version"
    tar -xzf "$TMP_DIR/helm.tar.gz" -C "$TMP_DIR" linux-amd64/helm
    sudo install -o root -g root -m 0755 "$TMP_DIR/linux-amd64/helm" /usr/local/bin/helm
    rm -rf "$TMP_DIR/linux-amd64" "$TMP_DIR/helm.tar.gz"
    ok "Helm $version installed."
}

install_helm_repos() {
    log "Adding Helm chart repositories..."
    local added=0
    for repo_name in "${!HELM_REPOS[@]}"; do
        local repo_url="${HELM_REPOS[$repo_name]}"
        if ! helm repo list 2>/dev/null | grep -q "^${repo_name}"; then
            helm repo add "$repo_name" "$repo_url" 2>/dev/null && added=$((added + 1)) || \
                warn "Failed to add Helm repo: $repo_name ($repo_url)"
        fi
    done
    if [[ $added -gt 0 ]]; then
        helm repo update 2>/dev/null || warn "Helm repo update had warnings."
        ok "$added Helm repos added and updated."
    else
        ok "All Helm repos already configured."
    fi
}

install_kubespray() {
    local dest="$PROJECT_ROOT/kubespray"
    if [[ -d "$dest" && -f "$dest/cluster.yml" ]]; then
        ok "Kubespray already present at $dest"
        return 0
    fi

    log "Downloading Kubespray $KUBESPRAY_VERSION..."
    download_safe "$KUBESPRAY_URL" "$TMP_DIR/kubespray.tar.gz" "Kubespray $KUBESPRAY_VERSION"
    mkdir -p "$dest"
    tar -xzf "$TMP_DIR/kubespray.tar.gz" --strip-components=1 -C "$dest"
    rm -f "$TMP_DIR/kubespray.tar.gz"

    # Install Kubespray Python dependencies (in a venv to avoid system conflicts)
    log "Installing Kubespray Python dependencies..."
    if [[ ! -d "$dest/.venv" ]]; then
        python3 -m venv "$dest/.venv"
    fi
    # shellcheck disable=SC1091
    source "$dest/.venv/bin/activate"
    pip install --quiet --upgrade pip 2>/dev/null
    pip install --quiet -r "$dest/requirements.txt" 2>/dev/null || \
        warn "Some Kubespray pip dependencies failed (check proxy)."
    deactivate
    ok "Kubespray $KUBESPRAY_VERSION installed at $dest"
}

install_argocd_cli() {
    if command -v argocd &>/dev/null; then
        ok "ArgoCD CLI already installed."
        return 0
    fi
    log "Installing ArgoCD CLI $ARGOCD_VERSION..."
    download_safe "$ARGOCD_URL" "$TMP_DIR/argocd" "ArgoCD CLI $ARGOCD_VERSION"
    sudo install -o root -g root -m 0755 "$TMP_DIR/argocd" /usr/local/bin/argocd
    rm -f "$TMP_DIR/argocd"
    ok "ArgoCD CLI installed."
}

install_yq() {
    if command -v yq &>/dev/null; then
        ok "yq already installed."
        return 0
    fi
    log "Installing yq $YQ_VERSION..."
    download_safe "$YQ_URL" "$TMP_DIR/yq" "yq $YQ_VERSION"
    sudo install -o root -g root -m 0755 "$TMP_DIR/yq" /usr/local/bin/yq
    rm -f "$TMP_DIR/yq"
    ok "yq installed."
}

install_k9s() {
    if command -v k9s &>/dev/null; then
        ok "k9s already installed."
        return 0
    fi
    log "Installing k9s $K9S_VERSION..."
    download_safe "$K9S_URL" "$TMP_DIR/k9s.tar.gz" "k9s $K9S_VERSION"
    tar -xzf "$TMP_DIR/k9s.tar.gz" -C "$TMP_DIR" k9s
    sudo install -o root -g root -m 0755 "$TMP_DIR/k9s" /usr/local/bin/k9s
    rm -f "$TMP_DIR/k9s" "$TMP_DIR/k9s.tar.gz"
    ok "k9s installed."
}

install_fullstack_apt_packages() {
    log "Checking full-stack APT packages..."
    local to_install=()
    for pkg in "${FULLSTACK_APT_PKGS[@]}"; do
        if ! dpkg -l "$pkg" 2>/dev/null | grep -q "^ii"; then
            to_install+=("$pkg")
        fi
    done
    if [[ ${#to_install[@]} -gt 0 ]]; then
        log "Installing ${#to_install[@]} additional packages: ${to_install[*]}"
        sudo apt-get update -qq
        sudo apt-get install -y -qq "${to_install[@]}" 2>&1 | tail -5
        ok "Full-stack packages installed."
    else
        ok "All full-stack packages already present."
    fi
}

install_openstack_client() {
    if command -v openstack &>/dev/null; then
        ok "OpenStack CLI (python-openstackclient) already installed."
        return 0
    fi
    log "Installing python-openstackclient..."
    pip install --quiet python-openstackclient python-heatclient python-neutronclient \
        python-cinderclient python-glanceclient 2>/dev/null || \
        { warn "OpenStack client pip install failed (check proxy). Trying with --user...";
          pip install --user --quiet python-openstackclient 2>/dev/null || \
            warn "OpenStack client install failed."; }
    ok "OpenStack CLI installed."
}

install_maas_cli() {
    if command -v maas &>/dev/null; then
        ok "MAAS CLI already installed."
        return 0
    fi
    log "Installing MAAS CLI..."
    sudo apt-get install -y -qq maas-cli 2>/dev/null || \
        { pip install --quiet python-libmaas 2>/dev/null || \
            warn "MAAS CLI install failed (not critical for KVM lab)."; }
    if command -v maas &>/dev/null; then
        ok "MAAS CLI installed."
    fi
}

install_ceph_tools() {
    if command -v ceph &>/dev/null; then
        ok "Ceph CLI tools already installed."
        return 0
    fi
    log "Installing Ceph CLI tools..."
    sudo apt-get install -y -qq ceph-common 2>/dev/null || \
        warn "Ceph CLI install failed (not critical — Rook deploys its own tools)."
    if command -v ceph &>/dev/null; then
        ok "Ceph CLI tools installed."
    fi
}

phase_tools_download() {
    header "PHASE T: Download & Install Platform Tools"
    log "Proxy mode: $PROXY_MODE"
    [[ "$PROXY_MODE" == "custom" ]] && log "Custom proxy: $PROXY_CUSTOM_URL"
    echo ""

    # --- Core infrastructure tools ---
    log "── Core Infrastructure Tools ──"
    install_kubectl
    install_helm
    install_yq
    install_k9s
    install_argocd_cli
    echo ""

    # --- Helm chart repositories ---
    log "── Helm Chart Repositories ──"
    install_helm_repos
    echo ""

    # --- Kubespray (Kubernetes installer) ---
    log "── Kubespray (Kubernetes Installer) ──"
    install_kubespray
    echo ""

    # --- Full-stack APT dependencies ---
    log "── Full-Stack APT Packages ──"
    install_fullstack_apt_packages
    echo ""

    # --- Cloud platform CLIs ---
    log "── Cloud Platform CLIs ──"
    install_openstack_client
    install_maas_cli
    install_ceph_tools
    echo ""

    # --- Summary ---
    header "TOOLS INSTALLATION SUMMARY"
    printf "  ${BLD}%-25s %-12s %-40s${RST}\n" "TOOL" "STATUS" "VERSION/PATH"
    printf "  %-25s %-12s %-40s\n" "─────────────────────────" "────────────" "────────────────────────────────────────"

    local tools_list=(
        "kubectl:kubectl version --client --short 2>/dev/null | awk '{print \$3}'"
        "helm:helm version --short 2>/dev/null | cut -d+ -f1"
        "yq:yq --version 2>/dev/null | awk '{print \$NF}'"
        "k9s:k9s version --short 2>/dev/null | head -1"
        "argocd:argocd version --client --short 2>/dev/null"
        "ansible:ansible --version 2>/dev/null | head -1 | awk '{print \$NF}'"
        "openstack:openstack --version 2>/dev/null | awk '{print \$2}'"
        "maas:maas --version 2>/dev/null || echo N/A"
        "ceph:ceph --version 2>/dev/null | awk '{print \$3}'"
        "jq:jq --version 2>/dev/null"
        "python3:python3 --version 2>/dev/null | awk '{print \$2}'"
    )

    for entry in "${tools_list[@]}"; do
        local tool_name="${entry%%:*}"
        local version_cmd="${entry#*:}"
        local status version
        if command -v "$tool_name" &>/dev/null; then
            status="${GRN}INSTALLED${RST}"
            version=$(eval "$version_cmd" 2>/dev/null || echo "unknown")
        else
            status="${YLW}MISSING${RST}"
            version="—"
        fi
        printf "  %-25s ${status}  %-40s\n" "$tool_name" "$version"
    done

    # Check Kubespray
    local ks_status ks_ver
    if [[ -f "$PROJECT_ROOT/kubespray/cluster.yml" ]]; then
        ks_status="${GRN}INSTALLED${RST}"
        ks_ver="$PROJECT_ROOT/kubespray/"
    else
        ks_status="${YLW}MISSING${RST}"
        ks_ver="—"
    fi
    printf "  %-25s ${ks_status}  %-40s\n" "kubespray" "$ks_ver"

    # Helm repos
    echo ""
    log "Helm Repositories:"
    helm repo list 2>/dev/null | head -15 || echo "  (none configured)"
    echo ""

    ok "Platform tools phase complete."
    log "All tools respect proxy mode '$PROXY_MODE'. Re-run with --no-proxy if behind no firewall."
}

# ======================= MAIN ===============================================
main() {
    echo "============================================================================"
    echo "  Data Center CLOS Lab Deployer v13.0"
    echo "  Generated by GitHub Copilot (Claude Opus 4.6) — $(date '+%Y-%m-%d %H:%M')"
    echo "============================================================================"

    # Ensure log directory exists
    mkdir -p "$(dirname "$LOG_FILE")"

    while [[ $# -gt 0 ]]; do
        case "$1" in
            --profile|-p)
                [[ $# -lt 2 ]] && die "--profile requires a value"
                AUTOMATION_PROFILE="$2"
                shift 2
                ;;
            --no-proxy|--direct)
                PROXY_MODE="direct"
                shift
                ;;
            --proxy-url)
                [[ $# -lt 2 ]] && die "--proxy-url requires a URL value"
                PROXY_MODE="custom"
                PROXY_CUSTOM_URL="$2"
                shift 2
                ;;
            --proxy)
                PROXY_MODE="corporate"
                shift
                ;;
            *)
                break
                ;;
        esac
    done

    # Apply proxy configuration based on CLI flags
    configure_proxy

    local action="${1:-deploy}"
    [[ $# -gt 0 ]] && shift

    # 'tools' action doesn't need a profile — skip profile/VM initialization
    if [[ "$action" == "tools" ]]; then
        mkdir -p "$TMP_DIR" "$PROJECT_ROOT"
        phase0_setup
        phase_tools_download
        return 0
    fi

    if [[ -n "$AUTOMATION_PROFILE" ]]; then
        apply_profile_settings "$AUTOMATION_PROFILE"
    else
        prompt_for_profile
    fi
    initialize_vm_catalog
    print_profile_summary
    require_lab_profile "$action"

    # For 'test' action, don't resolve targets (it takes a type, not VM names)
    local _test_args=("$@")
    if [[ "$action" != "test" ]]; then
        resolve_targets "$@" || exit 1
        if [[ ${#TARGET_VMS[@]} -lt ${#VM_DEPLOY_ORDER[@]} && ${#TARGET_VMS[@]} -gt 0 ]]; then
            log "Target VMs: ${TARGET_VMS[*]}"
        fi
    fi

    case "$action" in
        deploy)
            phase0_setup
            phase1_download
            phase2_process
            phase3_networks
            phase4_deploy
            phase5_validate
            phase5_5_server_config
            phase5_6_k8s_prep
            phase6_inventory
            status_report
            echo ""
            log "═══ ALL PHASES COMPLETE ═══"
            log "Next: ansible-playbook -i $INVENTORY_FILE $PROJECT_ROOT/validate_ssh.yml"
            ;;
        redeploy|--redeploy)
            phase0_setup
            log "Force-deleting target VMs: ${TARGET_VMS[*]}"
            for vm in "${TARGET_VMS[@]}"; do force_delete_vm "$vm"; done
            phase1_download
            phase2_process
            phase3_networks
            phase4_deploy
            phase5_validate
            phase5_5_server_config
            phase5_6_k8s_prep
            phase6_inventory
            status_report
            ;;
        destroy|--destroy)
            if [[ ${#TARGET_VMS[@]} -lt ${#VM_DEPLOY_ORDER[@]} ]]; then
                # Targeted destroy — no confirmation needed
                log "Destroying target VMs: ${TARGET_VMS[*]}"
                for vm in "${TARGET_VMS[@]}"; do force_delete_vm "$vm"; done
                ok "Targeted destroy complete."
            else
                teardown
            fi
            ;;
        status|--status)
            status_report
            ;;
        images|--images)
            mkdir -p "$IMG_DIR" "$TMP_DIR"
            phase1_download
            phase2_process
            ;;
        validate|--validate)
            phase5_validate
            ;;
        ssh)
            # Quick SSH into a single VM
            if [[ ${#TARGET_VMS[@]} -ne 1 ]]; then
                die "ssh requires exactly one VM target. Usage: $0 ssh <vm_name>"
            fi
            local vm="${TARGET_VMS[0]}"
            local ip="${VM_MGMT_IP[$vm]}"
            local type="${VM_TYPE[$vm]}"
            local user="${VM_USER[$type]}"
            local pass="${VM_PASS[$type]}"

            # Pre-flight checks
            if ! sudo virsh dominfo "$vm" &>/dev/null; then
                err "$vm does not exist. Deploy it first:"
                die "  $0 deploy $vm"
            fi
            local vm_state
            vm_state=$(sudo virsh domstate "$vm" 2>/dev/null || echo "unknown")
            if [[ "$vm_state" != "running" ]]; then
                warn "$vm is '$vm_state'. Starting..."
                sudo virsh start "$vm" 2>/dev/null || die "Failed to start $vm."
                log "Waiting 30s for $vm to boot..."
                sleep 30
            fi
            if ! sudo virsh net-info "$MGMT_NET_NAME" &>/dev/null || \
               [[ "$(sudo virsh net-info "$MGMT_NET_NAME" 2>/dev/null | awk '/Active:/{print $2}')" != "yes" ]]; then
                err "Management network '$MGMT_NET_NAME' is not active."
                die "  Run: $0 deploy  (or manually: sudo virsh net-start $MGMT_NET_NAME)"
            fi
            if ! ping -c 2 -W 3 "$ip" &>/dev/null; then
                # Static IP unreachable — check DHCP leases for actual IP
                local lease_ip
                lease_ip=$(sudo virsh net-dhcp-leases "$MGMT_NET_NAME" 2>/dev/null | \
                    grep -i "${vm,,}\|${vm}" | awk '{print $5}' | sed 's|/.*||' | head -1)
                if [[ -n "$lease_ip" && "$lease_ip" != "$ip" ]]; then
                    warn "Static IP $ip unreachable, but DHCP lease found at $lease_ip"
                    warn "MAC reservation mismatch. Syncing now..."
                    local correct_mac
                    correct_mac=$(gen_mac "$vm" "mgmt")
                    sudo virsh net-update "$MGMT_NET_NAME" delete ip-dhcp-host \
                        "<host name='${vm}'/>" --live --config 2>/dev/null || true
                    sudo virsh net-update "$MGMT_NET_NAME" add ip-dhcp-host \
                        "<host mac='${correct_mac}' name='${vm}' ip='${VM_MGMT_IP[$vm]}'/>" \
                        --live --config 2>/dev/null || true
                    if ping -c 2 -W 3 "$lease_ip" &>/dev/null; then
                        log "Using current lease IP $lease_ip (will use $ip after VM renews DHCP)."
                        ip="$lease_ip"
                    else
                        err "$vm lease IP ($lease_ip) also not reachable."
                        err "  - VM may still be booting (SONiC needs ~2-3 min)"
                        err "  - Try console: $0 console $vm"
                        die "  Wait and retry, or validate: $0 validate $vm"
                    fi
                else
                    err "$vm ($ip) is not reachable via ping."
                    err "Possible causes:"
                    err "  - VM is still booting (SONiC needs ~2-3 min for ZTP/DHCP)"
                    err "  - DHCP lease not acquired (check: sudo virsh net-dhcp-leases $MGMT_NET_NAME)"
                    err "  - Try console: $0 console $vm"
                    die "  Wait and retry, or validate: $0 validate $vm"
                fi
            fi

            log "SSH → $vm ($user@$ip)..."
            if [[ -n "$pass" ]]; then
                sshpass -p "$pass" ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "$user@$ip"
            else
                ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "$user@$ip"
            fi
            ;;
        console)
            # Quick console access to a single VM
            if [[ ${#TARGET_VMS[@]} -ne 1 ]]; then
                die "console requires exactly one VM target. Usage: $0 console <vm_name>"
            fi
            sudo virsh console "${TARGET_VMS[0]}"
            ;;
        test)
            # Deploy a single test VM of specified type for exploration
            # Usage: deploy_lab_v13.sh test sonic|ubuntu|chr
            local test_type="${_test_args[0]:-}"
            case "${test_type,,}" in
                sonic|ubuntu|chr) ;;
                *)
                    echo "Usage: $0 test <sonic|ubuntu|chr>"
                    echo ""
                    echo "Deploys a single test VM with management NIC only."
                    echo "After boot, auto-connects via SSH for exploration."
                    echo ""
                    echo "  $0 test sonic   — SONiC switch (admin/YourPaSsWoRd)"
                    echo "  $0 test ubuntu  — Ubuntu server (ubuntu/ubuntu)"
                    echo "  $0 test chr     — MikroTik CHR (admin/no password)"
                    exit 1
                    ;;
            esac

            local test_vm="Test_${test_type}"
            local test_ip="172.16.2.99"
            local test_ram test_user test_pass test_base test_fmt test_os mgmt_model="virtio"

            case "$test_type" in
                sonic)
                    test_ram=$SONIC_RAM; test_user="admin"; test_pass="YourPaSsWoRd"
                    mgmt_model="virtio"; test_os="ubuntu20.04"
                    if [[ "$SONIC_DISK_FORMAT" == "qcow2" ]]; then
                        test_base="$IMG_DIR/sonic-vs.qcow2"; test_fmt="qcow2"
                    else
                        test_base="$IMG_DIR/sonic-vs.img"; test_fmt="raw"
                    fi
                    ;;
                ubuntu)
                    test_ram=$SERVER_RAM; test_user="ubuntu"; test_pass="ubuntu"
                    test_os="ubuntu24.04"
                    test_base="$IMG_DIR/ubuntu-cloud.qcow2"; test_fmt="qcow2"
                    ;;
                chr)
                    test_ram=$CHR_RAM; test_user="admin"; test_pass=""
                    test_os="generic"
                    test_base="$IMG_DIR/chr.qcow2"; test_fmt="qcow2"
                    ;;
            esac

            header "TEST MODE: Single $test_type VM"
            log "VM: $test_vm | IP: $test_ip | Credentials: $test_user / ${test_pass:-<none>}"

            # Phase 0: prerequisites
            phase0_setup

            # Ensure images exist
            if [[ ! -f "$test_base" ]]; then
                # Set needed type for targeted download
                NEED_SONIC=false; NEED_UBUNTU=false; NEED_CHR=false
                case "$test_type" in
                    sonic)  NEED_SONIC=true ;;
                    ubuntu) NEED_UBUNTU=true ;;
                    chr)    NEED_CHR=true ;;
                esac
                phase1_download
                phase2_process
            fi
            [[ ! -f "$test_base" ]] && die "Base image missing: $test_base"

            # Ensure management network exists
            phase3_networks

            # Remove old test VM if exists
            force_delete_vm "$test_vm"

            # Add DHCP reservation for test VM
            local test_mac
            test_mac=$(gen_mac "$test_vm" "mgmt")
            sudo virsh net-update "$MGMT_NET_NAME" add ip-dhcp-host \
                "<host mac='${test_mac}' name='${test_vm}' ip='${test_ip}'/>" \
                --live --config 2>/dev/null || true

            # Create disk
            local test_disk="$DISK_DIR/${test_vm}.qcow2"
            sudo qemu-img create -f qcow2 -b "$test_base" -F "$test_fmt" "$test_disk" 20G >/dev/null

            # Cloud-init for Ubuntu only
            local extra_args=""
            if [[ "$test_type" == "ubuntu" ]]; then
                create_cloud_init_iso "$test_vm" "$test_user" "$test_pass"
                extra_args="--disk path=${CLOUD_INIT_DIR}/${test_vm}-cidata.iso,device=cdrom"
            fi

            # Deploy with mgmt NIC only (no fabric bridges)
            log "Deploying test VM..."
            if sudo virt-install \
                --name "$test_vm" \
                --ram "$test_ram" \
                --vcpus 2 \
                --disk path="$test_disk",format=qcow2,bus=virtio \
                $extra_args \
                --os-variant "$test_os" \
                --network network=${MGMT_NET_NAME},model=${mgmt_model},mac=${test_mac} \
                --graphics none \
                --console pty,target_type=serial \
                --serial pty \
                --virt-type kvm \
                --import \
                --noautoconsole >/dev/null 2>&1; then
                ok "$test_vm deployed successfully."
            else
                die "$test_vm deployment FAILED."
            fi

            # Wait and validate
            local wait_time=60
            [[ "$test_type" == "sonic" ]] && wait_time=180
            log "Waiting ${wait_time}s for $test_type to boot..."
            sleep $wait_time

            # SSH check
            local attempt=1 connected=false
            local ssh_opts="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=5"
            log "Attempting SSH connection..."
            while [[ $attempt -le 15 ]]; do
                if ping -c 1 -W 2 "$test_ip" &>/dev/null; then
                    local result=""
                    if [[ -n "$test_pass" ]]; then
                        result=$(sshpass -p "$test_pass" ssh $ssh_opts "$test_user@$test_ip" "echo ok" 2>/dev/null || true)
                    else
                        result=$(ssh $ssh_opts "$test_user@$test_ip" "echo ok" 2>/dev/null || true)
                    fi
                    if [[ "$result" == "ok" ]]; then
                        connected=true
                        break
                    fi
                fi
                printf "."
                attempt=$((attempt + 1))
                sleep 10
            done
            echo ""

            if $connected; then
                ok "SSH connectivity verified!"
                echo ""
                echo "============================================================================"
                echo "  TEST VM READY"
                echo "============================================================================"
                echo "  Type:        $test_type"
                echo "  VM Name:     $test_vm"
                echo "  IP Address:  $test_ip"
                echo "  Username:    $test_user"
                echo "  Password:    ${test_pass:-<none>}"
                echo "  SSH:         ssh ${test_user}@${test_ip}"
                echo "  Console:     sudo virsh console $test_vm"
                echo "  Destroy:     sudo virsh destroy $test_vm && sudo virsh undefine $test_vm --remove-all-storage"
                echo "============================================================================"
                echo ""
                log "Connecting via SSH now... (type 'exit' to disconnect)"
                echo "────────────────────────────────────────────────────────────────────────────"
                if [[ -n "$test_pass" ]]; then
                    sshpass -p "$test_pass" ssh $ssh_opts "$test_user@$test_ip"
                else
                    ssh $ssh_opts "$test_user@$test_ip"
                fi
            else
                warn "SSH not reachable after retries."
                echo ""
                echo "  Try manually:"
                echo "    ssh ${test_user}@${test_ip}  (password: ${test_pass:-<none>})"
                echo "    sudo virsh console $test_vm"
                echo ""
                echo "  Destroy when done:"
                echo "    sudo virsh destroy $test_vm && sudo virsh undefine $test_vm --remove-all-storage"
            fi
            ;;
        tools)
            # Download and install all platform tools (Helm, kubectl, Kubespray, etc.)
            phase0_setup
            phase_tools_download
            ;;
        *)
            echo "Usage: $0 [OPTIONS] <action> [vm1,vm2,...|group]"
            echo ""
            echo "Options:"
            echo "  --profile <name>    Set automation profile (win11_kvm, ubuntu_r620_kvm, real_hardware)"
            echo "  --no-proxy          Bypass corporate proxy (direct internet access)"
            echo "  --proxy-url <url>   Use custom proxy URL instead of corporate default"
            echo "  --proxy             Force corporate proxy (default behavior)"
            echo ""
            echo "Actions:"
            echo "  deploy    [targets] — Build VMs (idempotent, skips existing)"
            echo "  redeploy  [targets] — Force-delete + fresh deploy"
            echo "  destroy   [targets] — Tear down VMs (full teardown if no targets)"
            echo "  validate  [targets] — Re-run SSH connectivity checks"
            echo "  test      <type>    — Deploy single VM for testing (sonic|ubuntu|chr)"
            echo "  ssh       <vm>      — SSH directly into a VM"
            echo "  console   <vm>      — Attach virsh console to a VM"
            echo "  status              — Show all VM states + resource usage"
            echo "  images              — Download and verify images only"
            echo "  tools               — Download/install platform tools (Helm, kubectl, Kubespray, etc.)"
            echo ""
            echo "Targets (optional, default=all):"
            echo "  Single:   Spine_S1, Leaf_L2, Host12_1, Exit_Router1"
            echo "  Multiple: Spine_S1,Leaf_L1,Host12_1  (comma-separated)"
            echo "  Groups:   spines, leafs, border_leafs, switches, servers, routers, all"
            echo ""
            echo "Proxy examples:"
            echo "  $0 --no-proxy --profile win11_kvm deploy          # Direct internet (home lab)"
            echo "  $0 --proxy-url http://myproxy:3128 deploy         # Custom proxy"
            echo "  $0 --profile win11_kvm deploy                     # Corporate proxy (default)"
            echo ""
            echo "Examples:"
            echo "  $0 --profile win11_kvm deploy                     # Deploy all 18 VMs"
            echo "  $0 --profile ubuntu_r620_kvm redeploy spines      # Redeploy only spines"
            echo "  $0 --no-proxy --profile win11_kvm tools           # Download platform tools (no proxy)"
            echo "  $0 --profile win11_kvm validate Leaf_L1,Leaf_L2   # Validate specific leafs"
            echo "  $0 --profile win11_kvm test sonic                 # Deploy single SONiC for testing"
            echo "  $0 --profile win11_kvm ssh Spine_S1               # SSH into Spine_S1"
            exit 1
            ;;
    esac
}

main "$@"
